const paper4Data2025 = [{"topic": "12", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q1", "title": "Steel ball inside a hollow cone — circular motion &amp; angular speed", "pdf": "9702_m25_qp_42_Q1_Motion_in_a_circle.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["12.2.1"], "marks": 1, "answer": "An arrow <b>vertically downwards</b> labelled ‘weight’, and an arrow <b>perpendicular to the cone surface, pointing inwards and upwards</b>, labelled ‘normal contact force’ (the two arrows must be in the correct directions and correctly labelled)."}, {"label": "(b)", "codes": ["12.2.1", "12.2.2"], "marks": 2, "answer": "The <b>vertical component of the contact force equals the weight</b>, so there is no resultant force vertically. The <b>horizontal component of the contact force is the resultant force</b>, and it acts towards the centre of the circle — this provides the centripetal force that keeps the ball moving in a circle."}, {"label": "(c)", "codes": ["12.2.3", "12.2.4"], "marks": 3, "answer": "For a conical-pendulum type of motion the acceleration is <b>a = g tan 52°</b>, and a = v²/r:<br>9.81 × tan 52° = v²/0.15<br>v² = 0.15 × 9.81 × tan 52° = 1.88 m² s⁻²<br>v = <b>1.4 m s⁻¹</b>"}, {"label": "(d)", "codes": ["12.1.3"], "marks": 2, "answer": "v = rω, so ω = v/r = 1.4/0.15<br>= <b>9.3 rad s⁻¹</b><br>(Equivalently ω = √(g tan 52°/0.15) = 9.3 rad s⁻¹.)"}, {"label": "(e)", "codes": ["12.2.3"], "marks": 1, "answer": "The resultant (centripetal) force — hence the acceleration — is unchanged, and a = v²/r, so <b>v² is proportional to r</b>. Therefore increasing the speed requires a larger radius, so the ball moves up the cone to a circle of larger radius."}]}, {"topic": "13", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q2", "title": "Gravitational potential of a planet &amp; electric potential between plates", "pdf": "9702_m25_qp_42_Q2_Gravitational_fields.pdf", "marks": 7, "parts": [{"label": "(a)", "codes": ["13.4.2"], "marks": 3, "answer": "Sketch φ against x: a curve lying <b>entirely in the negative-φ region</b> for x between R and 4R, starting at (R, −φ) with a <b>continuously decreasing magnitude and continuously decreasing gradient</b> (concave up towards zero), and passing through <b>(2R, −½φ)</b> and <b>(4R, −¼φ)</b>. The potential is φ = −GM/x, so it halves as x doubles."}, {"label": "(b)", "codes": ["13.2.4", "13.4.2"], "marks": 2, "answer": "A geostationary satellite stays at the <b>same point</b> above the Earth, so its gravitational potential is constant: a <b>horizontal straight line from t = 0 to t = 24 hours</b>, starting at (0, −φ)."}, {"label": "(c)", "codes": ["18.2.1"], "marks": 2, "answer": "The field between the plates is uniform, so the potential falls uniformly: a <b>straight line with constant negative gradient from (0, V) to (d, 0)</b>, i.e. the potential decreases linearly from the positive plate to the negative plate."}]}, {"topic": "15", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q3", "title": "Thermal equilibrium, specific heat capacity &amp; ideal gas", "pdf": "9702_m25_qp_42_Q3_Ideal_gases.pdf", "marks": 12, "parts": [{"label": "(a)(i)", "codes": ["14.1.2"], "marks": 2, "answer": "P and Q are at the <b>same temperature</b>, so there is <b>no net transfer of thermal energy</b> between them."}, {"label": "(a)(ii)", "codes": ["14.3.1"], "marks": 3, "answer": "Energy is shared between P and Q, so Q = (mcΔT)<sub>P</sub> + (mcΔT)<sub>Q</sub>:<br>24 × 10³ = (0.54 × 390 × ΔT) + (0.37 × 910 × ΔT)<br>24 × 10³ = (210.6 + 336.7)ΔT = 547.3ΔT<br>ΔT = <b>44 K</b>"}, {"label": "(b)(i)", "codes": ["16.2.1"], "marks": 3, "answer": "Work done = pΔV = (1.6 × 10⁵) × (0.18 − 0.32)<br>= 1.6 × 10⁵ × (−0.14) = <b>−2.2 × 10⁴ J</b><br>(The volume decreases, so work is done <b>on</b> the gas.)"}, {"label": "(b)(ii)", "codes": ["15.2.2"], "marks": 2, "answer": "pV = NkT, so N = pV/kT<br>= (1.6 × 10⁵ × 0.18)/(1.38 × 10⁻²³ × 273)<br>= <b>7.6 × 10²⁴</b>"}, {"label": "(b)(iii)", "codes": ["15.3.3", "15.3.4"], "marks": 2, "answer": "½m⟨c²⟩ = ½m(c<sub>r.m.s.</sub>)² = (3/2)kT, so<br>c<sub>r.m.s.</sub> = √(3kT/m) = √[3 × 1.38 × 10⁻²³ × (210 + 273)/(4.7 × 10⁻²⁶)]<br>= <b>650 m s⁻¹</b>"}]}, {"topic": "17", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q4", "title": "Piezoelectric crystal — simple harmonic motion &amp; ultrasound", "pdf": "9702_m25_qp_42_Q4_Oscillations.pdf", "marks": 12, "parts": [{"label": "(a)", "codes": ["17.1.3"], "marks": 2, "answer": "ω = 2π/T = 2π/(0.15 × 10⁻⁶)<br>= <b>4.2 × 10⁷ rad s⁻¹</b>"}, {"label": "(b)", "codes": ["17.1.3"], "marks": 2, "answer": "a₀ = ω²x₀ = (4.2 × 10⁷)² × 40 × 10⁻⁶<br>= <b>7.1 × 10¹⁰ m s⁻²</b>"}, {"label": "(c)", "codes": ["17.2.2"], "marks": 3, "answer": "E = ½mω²x₀² = ½ × 2.4 × 10⁻⁴ × (4.2 × 10⁷)² × (40 × 10⁻⁶)²<br>= <b>340 J</b>"}, {"label": "(d)(i)", "codes": ["24.1.1", "24.1.2"], "marks": 2, "answer": "Apply an <b>alternating p.d.</b> across the crystal. The p.d. causes the crystal to <b>distort</b> (change shape) at the frequency of the alternating p.d., so the surface vibrates — and conversely an oscillating crystal generates an alternating e.m.f., so it can be used to generate ultrasound."}, {"label": "(d)(ii)", "codes": ["24.1.4", "24.1.5"], "marks": 3, "answer": "Z = ρc, so Z<sub>muscle</sub> = 1100 × 1600 = 1.76 × 10⁶ and Z<sub>bone</sub> = 1900 × 4100 = 7.79 × 10⁶ kg m⁻² s⁻¹.<br>Intensity reflection coefficient = (Z₁ − Z₂)²/(Z₁ + Z₂)²<br>= (7.79 − 1.76)²/(7.79 + 1.76)² = 0.40 (40%)<br>so percentage transmitted = <b>60%</b>"}]}, {"topic": "19", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q5", "title": "Capacitor network — series/parallel &amp; discharge through a resistor", "pdf": "9702_m25_qp_42_Q5_Capacitance.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["19.1.3"], "marks": 2, "answer": "For capacitors in series the charge is the same (Q = Q₁ = Q₂) and the p.d.s add (V = V₁ + V₂). Using V = Q/C:<br>Q/C = Q/C₁ + Q/C₂, which gives <b>1/C = 1/C₁ + 1/C₂</b>."}, {"label": "(b)", "codes": ["19.1.4"], "marks": 3, "answer": "Two equal capacitors C in series give C/2, so the total capacitance is C + C/2 = <b>3C/2</b>.<br>The total capacitance equals the gradient of the Q–V graph = 400 × 10⁻⁶/6.0.<br>C = (2 × 400 × 10⁻⁶)/(3 × 6.0) = <b>44 μF</b>"}, {"label": "(c)(i)", "codes": ["19.3.2"], "marks": 2, "answer": "τ = RC = 54 × 10³ × (3/2) × 44 × 10⁻⁶<br>= <b>3.6 s</b>"}, {"label": "(c)(ii)", "codes": ["19.3.3"], "marks": 2, "answer": "I = I₀e^(−t/RC), so 0.15 = e^(−t/3.6)<br>−t/3.6 = ln 0.15 = −1.90<br>t = <b>6.8 s</b>"}]}, {"topic": "20", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q6", "title": "Velocity selector — magnetic field, forces &amp; ion paths", "pdf": "9702_m25_qp_42_Q6_Magnetic_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["20.3.6"], "marks": 2, "answer": "For undeviated motion the forces balance: F<sub>B</sub> = F<sub>E</sub>, so Bqu = qE. With E = V/d this gives Bqu = qV/d, so <b>u = V/Bd</b>."}, {"label": "(b)", "codes": ["20.3.2", "20.3.6"], "marks": 3, "answer": "Eₖ = ½mu², so u = √(2Eₖ/m) = √(2 × 4.1 × 10⁻¹⁷/3.2 × 10⁻²⁷) = 1.6 × 10⁵ m s⁻¹.<br>B = V/(ud) = 980/(3.6 × 10⁻² × 1.6 × 10⁵)<br>= <b>0.17 T</b>"}, {"label": "(c)", "codes": ["20.3.6"], "marks": 1, "answer": "The expression u = V/Bd is <b>independent of mass and charge</b>, so the alpha particle also passes through undeviated at the same speed."}, {"label": "(d)", "codes": ["20.3.1", "20.2.2"], "marks": 3, "answer": "There is no resultant force, so the <b>magnetic force is upwards</b> (equal and opposite to the downward electric force). The ions are positive, so the conventional current is from left to right. Using Fleming’s left-hand rule, the magnetic field is <b>into the page</b>."}, {"label": "(e)", "codes": ["20.3.5"], "marks": 2, "answer": "A <b>curved path</b> inside the plates with a consistent direction of curvature and no discontinuity at entry or in curvature, deflecting <b>upwards</b> (the magnetic force now exceeds the electric force, so the ions are deflected towards the top plate)."}]}, {"topic": "20", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q7", "title": "Rod in a magnetic field — Faraday’s law &amp; induced e.m.f.", "pdf": "9702_m25_qp_42_Q7_Magnetic_fields.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["20.5.5"], "marks": 2, "answer": "The induced e.m.f. is <b>(directly) proportional to the rate of change of (magnetic) flux (linkage)</b>."}, {"label": "(b)(i)", "codes": ["20.5.5"], "marks": 2, "answer": "The rod accelerates uniformly, so its <b>velocity is proportional to time</b>. Fig. 7.2 shows the <b>e.m.f. is proportional to time</b>, so E is proportional to v."}, {"label": "(b)(ii)", "codes": ["20.5.3", "20.5.5"], "marks": 3, "answer": "With v = at, the distance moved in time Δt is atΔt, so the area swept out is L × atΔt. The flux cut is ΔΦ = B × (area) = BLatΔt, and E = ΔΦ/Δt = <b>BLat</b>."}, {"label": "(b)(iii)", "codes": ["20.5.5"], "marks": 2, "answer": "From Fig. 7.2, E = 0.30 × 10⁻³ V at t = 2.0 s, so<br>B = E/(Lat) = (0.30 × 10⁻³)/(0.45 × 7.8 × 2.0)<br>= <b>4.3 × 10⁻⁵ T</b>"}]}, {"topic": "22", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q8", "title": "Laser photons — energy, wavelength &amp; radiation force", "pdf": "9702_m25_qp_42_Q8_Quantum_physics.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["22.1.1", "22.1.2"], "marks": 2, "answer": "A photon is a <b>quantum of energy</b> of <b>electromagnetic radiation</b>."}, {"label": "(b)(i)", "codes": ["22.1.3"], "marks": 3, "answer": "ΔE = hc/λ, so λ = hc/ΔE<br>= (6.63 × 10⁻³⁴ × 3.00 × 10⁸)/(1.96 × 1.60 × 10⁻¹⁹)<br>= <b>6.3 × 10⁻⁷ m</b>"}, {"label": "(b)(ii)", "codes": ["22.1.3"], "marks": 1, "answer": "Number per unit time = power/energy per photon<br>= (1.0 × 10⁻²)/(1.96 × 1.60 × 10⁻¹⁹)<br>= <b>3.2 × 10¹⁶ s⁻¹</b>"}, {"label": "(b)(iii)", "codes": ["22.1.5"], "marks": 4, "answer": "Force = rate of change of momentum, and for a photon p = E/c.<br>Half the photons are absorbed (momentum change p) and half are reflected (momentum change 2p), so the average momentum change per photon is (p + 2p)/2 = 3p/2.<br>F = (3/2) × (E/c) × (number per second)<br>= (3/2) × [(1.96 × 1.60 × 10⁻¹⁹)/(3.00 × 10⁸)] × 3.2 × 10¹⁶<br>= <b>5.0 × 10⁻¹¹ N</b>"}]}, {"topic": "23", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q9", "title": "Polonium-193 decay — binding energy, half-life &amp; PET", "pdf": "9702_m25_qp_42_Q9_Nuclear_physics.pdf", "marks": 10, "parts": [{"label": "(a)(i)", "codes": ["23.2.2"], "marks": 1, "answer": "<b>Random</b> — one cannot predict when a particular nucleus will decay (or which nucleus will decay next)."}, {"label": "(a)(ii)", "codes": ["23.2.2"], "marks": 1, "answer": "<b>Spontaneous</b> — the decay is not affected by external or environmental factors."}, {"label": "(b)", "codes": ["23.2.4"], "marks": 1, "answer": "The <b>time for the activity (or number of nuclei) to halve</b>."}, {"label": "(c)", "codes": ["23.1.1"], "marks": 2, "answer": "Energy released = total binding energy of products − total binding energy of the parent nucleus:<br>= (189 × 7.826) + (4 × 7.074) − (193 × 7.774)<br>= 1479.1 + 28.3 − 1500.4 = <b>7.03 eV</b>"}, {"label": "(d)(i)", "codes": ["23.2.3"], "marks": 1, "answer": "The <b>decay constant</b> (the magnitude of the gradient of the ln(N/N₀)–t graph equals λ)."}, {"label": "(d)(ii)", "codes": ["23.2.5"], "marks": 2, "answer": "Decay constant λ = magnitude of gradient = 1.4/0.84.<br>Half-life = ln 2/λ = ln 2/(1.4/0.84)<br>= <b>0.42 ms</b>"}, {"label": "(e)(i)", "codes": ["24.3.3"], "marks": 1, "answer": "The emitted positrons <b>collide with electrons and annihilate</b>, producing gamma-ray photons."}, {"label": "(e)(ii)", "codes": ["24.3.1"], "marks": 1, "answer": "The half-life is <b>long enough</b> to allow the investigation to be carried out, but <b>not so long</b> that the patient is exposed to radiation unnecessarily."}]}, {"topic": "25", "paper": "9702/42/F/M/25", "paper_full": "March 2025 · Paper 42", "qnum": "Q10", "title": "The Sun — rotation, redshift &amp; luminosity", "pdf": "9702_m25_qp_42_Q10_Astronomy_and_cosmology.pdf", "marks": 11, "parts": [{"label": "(a)(i)", "codes": ["25.1.1"], "marks": 1, "answer": "The <b>total power of radiation emitted</b> (by the star)."}, {"label": "(a)(ii)", "codes": ["25.1.3", "25.1.4"], "marks": 3, "answer": "A standard candle has a <b>known luminosity</b>. Measure the <b>radiant flux intensity</b> F received at the Earth, then use <b>F = L/(4πd²)</b> to calculate the distance d to the galaxy."}, {"label": "(b)(i)", "codes": ["25.3.2"], "marks": 3, "answer": "The two limbs of the Sun rotate in opposite directions, so the light from X and Y shows a rotational Doppler shift with Δλ = 656.2877 − 656.2831 nm. Using Δλ/λ = v/c and v = 2πR/T:<br>R = vT/2π = [3.00 × 10⁸ × (656.2877 − 656.2831)/656.2831] × (2.07 × 10⁶)/2π<br>= <b>6.93 × 10⁸ m</b>"}, {"label": "(b)(ii)", "codes": ["25.3.2"], "marks": 2, "answer": "Point Z is <b>moving towards the Earth</b>, so its light is blue-shifted: the <b>observed wavelength from Z is less than the emitted wavelength</b>."}, {"label": "(b)(iii)", "codes": ["25.2.2"], "marks": 2, "answer": "L = 4πσr²T⁴<br>3.8 × 10²⁶ = 4π × 5.67 × 10⁻⁸ × (6.93 × 10⁸)² × T⁴<br>T = <b>5800 K</b>"}]}, {"topic": "13", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q1", "title": "Gravitational potential &amp; field of Mars — satellite orbit", "pdf": "9702_s25_qp_41_Q1_Gravitational_fields.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["13.4.1"], "marks": 2, "answer": "The <b>work done per unit mass</b><br>in moving a small test mass <b>from infinity to the point</b>."}, {"label": "(b)(i)", "codes": ["13.4.3", "13.2.2"], "marks": 3, "answer": "The satellite moves from r₁ = (3.4 + 1.7) × 10⁶ = 5.1 × 10⁶ m to r₂ = (3.4 + 6.8) × 10⁶ = 10.2 × 10⁶ m from the centre of Mars. Using ΔE<sub>P</sub> = GMm(1/r₁ − 1/r₂):<br>5.1 × 10⁸ = 6.67 × 10⁻¹¹ × M × 122 × [(5.1 × 10⁶)⁻¹ − (10.2 × 10⁶)⁻¹]<br>M = <b>6.4 × 10²³ kg</b>"}, {"label": "(b)(ii)", "codes": ["13.4.2"], "marks": 2, "answer": "φ = −GM/R = −(6.67 × 10⁻¹¹ × 6.4 × 10²³)/(3.4 × 10⁶)<br>= <b>−1.3 × 10⁷ J kg⁻¹</b>"}, {"label": "(c)(i)", "codes": ["13.2.4"], "marks": 1, "answer": "The satellite stays over the same point of Mars, so its period equals Mars’s rotation period: <b>Mars takes (just under) 25 hours to rotate once on its axis</b>."}, {"label": "(c)(ii)", "codes": ["13.2.4"], "marks": 1, "answer": "The orbit is <b>equatorial</b>, and/or the satellite orbits <b>in the same direction as the rotation of Mars</b>."}]}, {"topic": "18", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q2", "title": "Helium atom model — Coulomb’s law, electron orbits &amp; field strength", "pdf": "9702_s25_qp_41_Q2_Electric_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["18.3.2"], "marks": 2, "answer": "The (electric) force between two point charges is <b>(directly) proportional to the product of their charges</b> and <b>inversely proportional to the square of their separation</b>."}, {"label": "(b)(i)", "codes": ["18.3.1"], "marks": 1, "answer": "The helium nucleus contains two protons, so its charge is <b>+2e</b>."}, {"label": "(b)(ii)", "codes": ["18.3.2"], "marks": 1, "answer": "F = Qq/(4πε₀r²) = 2 × (1.60 × 10⁻¹⁹)²/[4π × 8.85 × 10⁻¹² × (170 × 10⁻¹²)²]<br>= <b>1.6 × 10⁻⁸ N</b>"}, {"label": "(c)(i)", "codes": ["18.3.2"], "marks": 2, "answer": "The electric force provides the centripetal force: F = mv²/r, so<br>v = √(Fr/m) = √(1.6 × 10⁻⁸ × 170 × 10⁻¹² / 9.11 × 10⁻³¹)<br>= <b>1.7 × 10⁶ m s⁻¹</b>"}, {"label": "(c)(ii)", "codes": ["18.3.2"], "marks": 2, "answer": "v = 2πr/T, so T = 2πr/v = 2π × 170 × 10⁻¹² / (1.7 × 10⁶)<br>= <b>6.2 × 10⁻¹⁶ s</b><br>(Equivalently F = 4π²mr/T² gives the same period.)"}, {"label": "(d)(i)", "codes": ["18.4.1"], "marks": 2, "answer": "E ∝ Q/r². The other electron has charge e at a distance of 340 pm, and the nucleus has charge 2e at 170 pm, so<br>ratio = [e/(340 × 10⁻¹²)²]/[2e/(170 × 10⁻¹²)²] = (170)²/(2 × 340)² = <b>0.13</b>"}, {"label": "(d)(ii)", "codes": ["18.3.2"], "marks": 1, "answer": "The other electron exerts a small repulsive force, so the resultant inward force is slightly less than 1.6 × 10⁻⁸ N — hence the <b>speed of the electron is slightly lower</b> (or its period slightly greater)."}]}, {"topic": "14", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q3", "title": "Specific latent heat — vaporisation vs fusion &amp; ice–water mixture", "pdf": "9702_s25_qp_41_Q3_Temperature.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["14.3.2"], "marks": 2, "answer": "The <b>(thermal) energy per unit mass</b> required to <b>change state at constant temperature</b>."}, {"label": "(b)", "codes": ["14.3.2"], "marks": 3, "answer": "Vaporisation involves a <b>much larger increase in the separation (or volume) of the molecules</b> than fusion, so <b>much more work has to be done against the intermolecular forces</b> — a much larger increase in molecular potential energy. Since the kinetic energy of the molecules is unchanged in either change of state, more thermal energy is needed to vaporise a substance."}, {"label": "(c)", "codes": ["14.3.1", "14.3.2"], "marks": 4, "answer": "Heat lost by the water = heat to melt the ice + heat to warm the melted water. Using Q = mcΔθ and Q = mL:<br>(37.0 × L) + (37.0 × 4.18 × 10.3) = 208 × 4.18 × (26.4 − 10.3)<br>37.0L + 1593 = 14000<br>L = <b>335 J g⁻¹</b>"}]}, {"topic": "16", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q4", "title": "Internal energy &amp; the first law of thermodynamics", "pdf": "9702_s25_qp_41_Q4_Thermodynamics.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["16.1.1"], "marks": 2, "answer": "The <b>sum of the (randomly distributed) kinetic and potential energies</b> of the particles of the system — the total energy of the random motion of its particles."}, {"label": "(a)(ii)", "codes": ["16.1.1", "15.3.4"], "marks": 2, "answer": "For an ideal gas there are no intermolecular forces, so the <b>potential energy is zero</b> and the internal energy equals the <b>total kinetic energy of the molecules</b>. The average kinetic energy of the molecules is proportional to the (thermodynamic) temperature, so the internal energy is directly proportional to the thermodynamic temperature."}, {"label": "(b)", "codes": ["16.2.2"], "marks": 4, "answer": "<b>Compression</b> (T → 3T): internal energy rises threefold, so ΔU = +2U; work done on the gas = +W. From the first law ΔU = q + W, so thermal energy supplied q = 2U − W.<br><b>Cooling at constant volume</b> (3T → 2T): work done = 0; the internal energy falls from 3U to 2U, so ΔU = −U; hence thermal energy supplied q = ΔU = −U."}]}, {"topic": "17", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q5", "title": "Floating block — simple harmonic motion &amp; energy", "pdf": "9702_s25_qp_41_Q5_Oscillations.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["17.1.1"], "marks": 1, "answer": "The oscillation extends from h = 0.8 m to h = 2.0 m about the equilibrium at h = 1.4 m, so the amplitude = <b>0.60 m</b>."}, {"label": "(a)(ii)", "codes": ["17.1.3"], "marks": 1, "answer": "The line is a straight line through the origin, showing a ∝ −(displacement), so the <b>oscillations are simple harmonic</b>."}, {"label": "(b)", "codes": ["17.1.3", "17.2.2", "17.1.1"], "marks": 3, "answer": "Any three of: the <b>mean/equilibrium position is at h = 1.4 m</b>; the <b>total energy of the oscillations is 9.0 J</b>; the <b>angular frequency is 1.2 rad s⁻¹</b> (period 5.1 s, or frequency 0.19 Hz); the <b>maximum speed is 0.73 m s⁻¹</b>; the <b>mass of the block is 33 kg</b>."}, {"label": "(c)", "codes": ["17.2.1"], "marks": 3, "answer": "A <b>U-shaped curve</b> resting on the h-axis (minimum at E<sub>P</sub> = 0), drawn between h = 0.8 m and h = 2.0 m with the <b>minimum at h = 1.4 m</b> and both end-points at <b>E<sub>P</sub> = 9.0 J</b> (since E<sub>P</sub> = total energy − E<sub>K</sub>)."}]}, {"topic": "21", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q6", "title": "Rectification &amp; smoothing — a.c. to d.c.", "pdf": "9702_s25_qp_41_Q6_Alternating_currents.pdf", "marks": 12, "parts": [{"label": "(a)(i)", "codes": ["21.2.1"], "marks": 1, "answer": "The <b>conversion of an alternating current (a.c.) into a direct current (d.c.)</b>."}, {"label": "(a)(ii)", "codes": ["21.2.4"], "marks": 1, "answer": "To <b>smooth</b> the rectified output (reduce the ripple)."}, {"label": "(b)(i)", "codes": ["21.1.2", "21.1.1"], "marks": 2, "answer": "A = 12 V (the peak value), and B = 2π/T = 2π/(20 × 10⁻³)<br>= <b>310 rad s⁻¹</b>"}, {"label": "(b)(ii)", "codes": ["21.2.1"], "marks": 1, "answer": "<b>Full-wave</b> rectification (both halves of each cycle are used)."}, {"label": "(b)(iii)", "codes": ["21.2.3"], "marks": 2, "answer": "Four diodes connected as a <b>bridge rectifier</b> — a diamond/lattice of four diodes (each with the correct circuit symbol), with the a.c. input connected across one diagonal and the output taken across the other."}, {"label": "(b)(iv)", "codes": ["19.3.3", "21.2.4"], "marks": 3, "answer": "During discharge V = V₀e^(−t/τ). From Fig. 6.2 the p.d. falls from 12 V to 8.0 V in 7.3 ms:<br>8.0 = 12e^(−7.3 × 10⁻³/τ)<br>τ = −7.3 × 10⁻³/ln(8.0/12) = <b>0.018 s</b>"}, {"label": "(c)", "codes": ["19.3.2"], "marks": 2, "answer": "τ = RC, so R = τ/C = 0.018/(570 × 10⁻⁶)<br>= <b>32 Ω</b>"}]}, {"topic": "20", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q7", "title": "Magnetic fields — flux density, force &amp; velocity selector", "pdf": "9702_s25_qp_41_Q7_Magnetic_fields.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["20.2.3"], "marks": 2, "answer": "Magnetic flux density is the <b>force per unit length per unit current</b> acting on a (straight) conductor placed <b>perpendicular to the field</b>."}, {"label": "(b)(i)", "codes": ["20.3.2"], "marks": 1, "answer": "F = <b>BQv</b> (with the velocity perpendicular to the magnetic field)."}, {"label": "(b)(ii)", "codes": ["20.3.1"], "marks": 1, "answer": "An arrow at Y pointing <b>vertically upwards</b> (from Fleming’s left-hand rule for a positive charge)."}, {"label": "(b)(iii)", "codes": ["20.3.5"], "marks": 1, "answer": "A <b>circular path curving upwards</b> through the field (the force is always perpendicular to the velocity, so it acts as a centripetal force)."}, {"label": "(c)(i)", "codes": ["20.3.6"], "marks": 3, "answer": "Apply an <b>electric field vertically downwards</b> so that the <b>electric force on the particle is in the opposite direction to the magnetic force</b>. The particle then passes straight through to Z when the <b>magnitudes of the electric and magnetic forces are equal</b>."}, {"label": "(c)(ii)", "codes": ["20.3.6"], "marks": 2, "answer": "EQ = BQv, so <b>v = E/B</b>."}]}, {"topic": "22", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q8", "title": "Electron &amp; positron — de Broglie wavelength &amp; annihilation", "pdf": "9702_s25_qp_41_Q8_Quantum_physics.pdf", "marks": 13, "parts": [{"label": "(a)", "codes": ["22.3.3"], "marks": 1, "answer": "The <b>wavelength associated with a moving particle</b>."}, {"label": "(b)", "codes": ["22.3.4"], "marks": 2, "answer": "λ = h/p = h/mv = 6.63 × 10⁻³⁴/(9.11 × 10⁻³¹ × 4.9 × 10⁷)<br>= <b>1.5 × 10⁻¹¹ m</b>"}, {"label": "(c)", "codes": ["11.1.8"], "marks": 2, "answer": "Similarity: they have the <b>same mass</b> (or the same magnitude of charge, or both are leptons).<br>Difference: the <b>electron has negative charge while the positron has positive charge</b> (the positron is the antiparticle of the electron)."}, {"label": "(d)(i)", "codes": ["24.3.3"], "marks": 1, "answer": "<b>Annihilation</b> (a particle–antiparticle reaction)."}, {"label": "(d)(ii)", "codes": ["23.1.1", "24.3.3"], "marks": 2, "answer": "The electron and positron disappear — <b>their mass is converted into energy</b>, and this mass–energy becomes the energy of the two gamma-ray photons."}, {"label": "(d)(iii)", "codes": ["24.3.4"], "marks": 1, "answer": "Two photons are produced <b>travelling in opposite directions</b> so that <b>momentum is conserved</b> (the initial total momentum is zero)."}, {"label": "(d)(iv)", "codes": ["22.1.4"], "marks": 1, "answer": "E<sub>k</sub> = ½mv² = ½ × 9.11 × 10⁻³¹ × (4.9 × 10⁷)²<br>= <b>1.1 × 10⁻¹⁵ J</b>"}, {"label": "(d)(v)", "codes": ["23.1.1", "22.1.3"], "marks": 3, "answer": "Each of the two gamma photons carries the rest energy of one particle plus its kinetic energy:<br>E = mc² + E<sub>k</sub> = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² + 1.1 × 10⁻¹⁵ = 8.3 × 10⁻¹⁴ J.<br>Using E = hc/λ:<br>λ = hc/E = (6.63 × 10⁻³⁴ × 3.00 × 10⁸)/(8.3 × 10⁻¹⁴) = <b>2.39 × 10⁻¹² m</b>"}]}, {"topic": "23", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q9", "title": "Radioactive decay — activity, decay constant &amp; half-life", "pdf": "9702_s25_qp_41_Q9_Nuclear_physics.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["23.2.3"], "marks": 1, "answer": "The <b>number of nuclear disintegrations per unit time</b>."}, {"label": "(b)", "codes": ["23.2.6"], "marks": 3, "answer": "The <b>activity is proportional to the number of undecayed nuclei</b> (A = λN), and the activity equals the rate of decrease of N, so dN/dt = −λN — the number of nuclei falls at a rate proportional to itself, giving an <b>exponential variation</b>."}, {"label": "(c)(i)", "codes": ["23.2.6"], "marks": 2, "answer": "A = A₀e^(−λt), so 120 = 180e^(−λ × 8.4)<br>e^(−8.4λ) = 120/180 = 0.667<br>λ = −ln 0.667/8.4 = <b>0.048 min⁻¹</b>"}, {"label": "(c)(ii)", "codes": ["23.2.5"], "marks": 1, "answer": "Half-life = ln 2/λ = ln 2/0.048 = <b>14 min</b>"}, {"label": "(c)(iii)", "codes": ["23.2.6"], "marks": 3, "answer": "An exponential decay curve starting at (0, 180 Bq), with a <b>negative gradient that decreases in magnitude</b>, passing through (8.4, 120) and (14, 90), and approaching the t-axis by t = 24 min."}]}, {"topic": "25", "paper": "9702/41/M/J/25", "paper_full": "June 2025 · Paper 41", "qnum": "Q10", "title": "Hubble’s law &amp; redshift — galaxy recession", "pdf": "9702_s25_qp_41_Q10_Astronomy_and_cosmology.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["25.3.4"], "marks": 2, "answer": "The <b>speed of recession of a galaxy is (directly) proportional to its distance</b> from the observer (v = H₀d), where the speed is that of the galaxy receding from the observer and d is its distance from the observer."}, {"label": "(b)(i)", "codes": ["25.3.2"], "marks": 2, "answer": "The observed wavelength is <b>longer than the emitted wavelength (red-shifted)</b>, so the <b>galaxy is receding from the Earth</b> (the Doppler shift of the light)."}, {"label": "(b)(ii)", "codes": ["25.3.2"], "marks": 2, "answer": "Δλ/λ = v/c<br>(4.91 − 4.62)/4.62 = v/(3.00 × 10⁸)<br>v = <b>1.9 × 10⁷ m s⁻¹</b>"}, {"label": "(b)(iii)", "codes": ["25.2.1"], "marks": 2, "answer": "The wavelength of maximum intensity is <b>inversely proportional to the temperature</b> (Wien’s law). The observed wavelength is too high (red-shifted), so the <b>determined temperature is too low</b> compared with the true value."}, {"label": "(c)", "codes": ["25.3.4"], "marks": 2, "answer": "v = H₀d, so d = v/H₀ = (1.9 × 10⁷)/(2.3 × 10⁻¹⁸)<br>= <b>8.3 × 10²⁴ m</b>"}]}, {"topic": "12", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q1", "title": "Bicycle chain &amp; cogs — radian, angular speed &amp; period", "pdf": "9702_s25_qp_42_Q1_Motion_in_a_circle.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["12.1.1"], "marks": 1, "answer": "The <b>angle subtended at the centre of a circle by an arc whose length is equal to the radius</b>."}, {"label": "(b)(i)", "codes": ["12.1.3"], "marks": 2, "answer": "v = rω, so ω = v/r = 17/0.46<br>= <b>37 rad s⁻¹</b>"}, {"label": "(b)(ii)", "codes": ["12.1.3"], "marks": 2, "answer": "T = 2πr/v = 2π × 0.46/17 (or T = 2π/ω = 2π/37)<br>= <b>0.17 s</b>"}, {"label": "(b)(iii)", "codes": ["12.1.1"], "marks": 1, "answer": "distance moved = circumference of the small cog = 2πr = 2π × 0.038<br>= <b>0.24 m</b>"}, {"label": "(b)(iv)", "codes": ["12.1.1"], "marks": 2, "answer": "angle = arc length/radius = 0.24/0.15<br>= <b>1.6 rad</b>"}, {"label": "(c)", "codes": ["12.1.3"], "marks": 2, "answer": "The rear wheel still rotates at the same angular speed (the bicycle speed is unchanged), but the rear cog is now smaller, so <b>point X on the chain moves through a smaller distance in the same time</b> — the linear speed of the chain decreases. The large cog (fixed to the pedals) has the same radius, so the <b>angular speed of the pedals decreases</b>."}]}, {"topic": "20", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q2", "title": "Gravitational &amp; magnetic fields of the Earth", "pdf": "9702_s25_qp_42_Q2_Magnetic_fields.pdf", "marks": 12, "parts": [{"label": "(a)(i)", "codes": ["13.1.1"], "marks": 2, "answer": "A gravitational field line shows the <b>direction of the (gravitational) force</b> that would act on a small <b>test mass</b> placed at that point."}, {"label": "(a)(ii)", "codes": ["13.1.2"], "marks": 2, "answer": "At least four <b>radial lines</b> from the Earth’s surface, evenly spaced around it, with arrows pointing <b>towards the centre of the Earth</b>."}, {"label": "(b)(i)", "codes": ["20.1.2", "20.4.1"], "marks": 1, "answer": "The <b>top pole is labelled S and the bottom pole is labelled N</b> (the geographic north pole is near the Earth’s magnetic south pole)."}, {"label": "(b)(ii)", "codes": ["20.1.2", "20.4.1"], "marks": 2, "answer": "At the poles: at least two field lines on either side of each pole, <b>clustered close together</b>, leaving the surface approximately <b>perpendicular to it</b> and curving away from the pole axis. Above the equator: at least one field line on each side <b>looping from one hemisphere to the other</b>, passing above the surface near the equator approximately <b>parallel to the surface</b>."}, {"label": "(c)(i)", "codes": ["13.1.2"], "marks": 2, "answer": "The gravitational field lines are <b>evenly spaced</b> around the surface and all point <b>perpendicular to the surface</b> (towards the centre), so the field has the same magnitude and direction at every point on the surface — it does not vary around the surface."}, {"label": "(c)(ii)", "codes": ["20.1.2", "20.2.3"], "marks": 3, "answer": "The magnetic field is <b>strongest at the poles and weakest near the Equator</b>. It is <b>perpendicular to the surface at the poles</b> and <b>parallel to the surface near the Equator</b>, with the angle to the surface increasing from the Equator towards the poles."}]}, {"topic": "14", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q3", "title": "Specific heat capacity &amp; work done — heated aluminium block", "pdf": "9702_s25_qp_42_Q3_Temperature.pdf", "marks": 13, "parts": [{"label": "(a)", "codes": ["14.3.1"], "marks": 2, "answer": "The <b>(thermal) energy per unit mass</b> required to raise the temperature of the substance by <b>unit temperature (1 K or 1 °C)</b>."}, {"label": "(b)(i)", "codes": ["14.3.1"], "marks": 2, "answer": "density = mass/volume, so mass = ρV = 2.700 × 10³ × 3.612 × 10⁻³<br>= <b>9.75 kg</b>"}, {"label": "(b)(ii)", "codes": ["14.3.1"], "marks": 1, "answer": "The mass is constant, so V = V₀ × (ρ₀/ρ) = 3.612 × 10⁻³ × (2.700/2.620)<br>= <b>3.722 × 10⁻³ m³</b>"}, {"label": "(b)(iii)", "codes": ["16.2.1"], "marks": 2, "answer": "W = pΔV = 1.01 × 10⁵ × (3.722 − 3.612) × 10⁻³<br>= <b>11.1 J</b>"}, {"label": "(b)(iv)", "codes": ["16.2.1"], "marks": 2, "answer": "The <b>volume of the block increases</b>, so it pushes against the atmosphere and <b>work is done against the atmosphere</b> — the work done on the block is therefore <b>negative</b>."}, {"label": "(b)(v)", "codes": ["16.2.2", "14.3.1"], "marks": 3, "answer": "From the first law ΔU = q + W, the thermal energy supplied is q = ΔU − W = 4.38 × 10⁶ + 11.1 J (since W is negative).<br>Specific heat capacity = q/(mΔθ) = 4.38 × 10⁶/(9.75 × 500)<br>= <b>898 J kg⁻¹ °C⁻¹</b>"}, {"label": "(c)", "codes": ["16.2.1"], "marks": 1, "answer": "Doubling the pressure would double the work done, but the work done (11.1 J) is <b>negligible compared with the change in internal energy (4.38 MJ)</b>, so the specific heat capacity would be <b>unchanged</b>."}]}, {"topic": "15", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q4", "title": "Ideal gases — kinetic theory &amp; mean kinetic energy", "pdf": "9702_s25_qp_42_Q4_Ideal_gases.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["15.2.2"], "marks": 1, "answer": "T is the <b>thermodynamic temperature</b> (in kelvin)."}, {"label": "(a)(ii)", "codes": ["15.2.3"], "marks": 1, "answer": "B is the <b>Boltzmann constant</b> (k)."}, {"label": "(b)(i)", "codes": ["15.3.2", "15.3.3"], "marks": 2, "answer": "m is the <b>mass of one molecule</b> of the gas, and ⟨c²⟩ is the <b>mean-square speed</b> of the molecules."}, {"label": "(b)(ii)", "codes": ["15.3.4"], "marks": 2, "answer": "Equating pV from the two equations: NBT/A = ⅓Nm⟨c²⟩. The mean kinetic energy is E<sub>k</sub> = ½m⟨c²⟩, so<br>E<sub>k</sub> = <b>3BT/2A</b>"}, {"label": "(c)", "codes": ["15.3.3"], "marks": 2, "answer": "A line with a positive gradient passing through the origin, becoming a <b>smooth curve with a decreasing positive gradient</b> (since c<sub>r.m.s.</sub> ∝ √T)."}]}, {"topic": "17", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q5", "title": "Simple harmonic motion — displacement, velocity &amp; phase", "pdf": "9702_s25_qp_42_Q5_Oscillations.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["17.1.3"], "marks": 2, "answer": "Motion in which the <b>acceleration is (directly) proportional to the displacement</b> and is <b>always directed towards a fixed point</b> (in the opposite direction to the displacement)."}, {"label": "(b)(i)", "codes": ["17.1.1"], "marks": 1, "answer": "period = 2π/ω = 2π/16<br>= <b>0.39 s</b>"}, {"label": "(b)(ii)", "codes": ["17.1.3", "17.1.4"], "marks": 2, "answer": "v₀ = ωx₀, so x₀ = v₀/ω = 0.56/16<br>= <b>0.035 m</b>"}, {"label": "(b)(iii)", "codes": ["17.1.4"], "marks": 1, "answer": "v = ±ω√(x₀² − x²) = <b>±16√(0.035² − x²)</b>"}, {"label": "(b)(iv)", "codes": ["17.1.5"], "marks": 3, "answer": "A <b>closed loop (ellipse) surrounding the origin</b>, crossing the x-axis (v = 0) at <b>x = ±3.5 cm</b> and crossing the v-axis (x = 0) at <b>v = ±0.56 m s⁻¹</b>."}]}, {"topic": "18", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q6", "title": "Electric fields &amp; X-rays — an accelerated electron", "pdf": "9702_s25_qp_42_Q6_Electric_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["18.2.1"], "marks": 1, "answer": "Plate X is <b>negative (−)</b> and plate Y is <b>positive (+)</b> (the electron accelerates towards the positive plate)."}, {"label": "(b)(i)", "codes": ["18.2.1"], "marks": 2, "answer": "E = V/x = 58 × 10³/0.041<br>= <b>1.4 × 10⁶ N C⁻¹</b> (equivalent to V m⁻¹)"}, {"label": "(b)(ii)", "codes": ["18.2.2"], "marks": 2, "answer": "ma = eE, so a = eE/m = (1.60 × 10⁻¹⁹ × 1.41 × 10⁶)/9.11 × 10⁻³¹<br>= <b>2.5 × 10¹⁷ m s⁻²</b>"}, {"label": "(c)(i)", "codes": ["24.2.1"], "marks": 3, "answer": "The electron gains kinetic energy eV, which is converted to a photon at the minimum wavelength: eV = hc/λ.<br>λ = hc/eV = (6.63 × 10⁻³⁴ × 3.00 × 10⁸)/(1.60 × 10⁻¹⁹ × 58 × 10³)<br>= 2.1 × 10⁻¹¹ m = <b>21 pm</b>"}, {"label": "(c)(ii)", "codes": ["24.2.2"], "marks": 1, "answer": "<b>X-rays</b>."}, {"label": "(c)(iii)", "codes": ["24.2.2"], "marks": 2, "answer": "The X-rays are passed into the structure and the <b>transmitted waves are detected</b>. Different parts of the structure <b>absorb different fractions of the energy</b>, and the differences in the detected/transmitted intensities are used to form the image."}]}, {"topic": "19", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q7", "title": "Capacitor discharge — charge, resistance &amp; time constant", "pdf": "9702_s25_qp_42_Q7_Capacitance.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["19.1.2"], "marks": 1, "answer": "V<sub>C</sub> = V<sub>R</sub> — the p.d. across the capacitor equals the p.d. across the resistor (they are connected in parallel)."}, {"label": "(b)(i)", "codes": ["19.1.2"], "marks": 2, "answer": "C = Q/V = 7.2 × 10⁻³/12 = 6.0 × 10⁻⁴ F<br>= <b>600 μF</b>"}, {"label": "(b)(ii)", "codes": ["19.1.2"], "marks": 2, "answer": "R = V/I = 12/(1.5 × 10⁻³) = 8000 Ω<br>= <b>8.0 kΩ</b>"}, {"label": "(b)(iii)", "codes": ["19.3.2"], "marks": 2, "answer": "τ = RC = 8000 × 6.0 × 10⁻⁴<br>= <b>4.8 s</b>"}, {"label": "(c)", "codes": ["19.3.3"], "marks": 3, "answer": "Fig. 7.2 and Fig. 7.3 show that <b>charge and current are both directly proportional to the p.d.</b> (so Q ∝ I), and the <b>current is the rate of change of charge</b>. Hence dQ/dt ∝ Q — the charge decreases at a rate proportional to itself, giving an <b>exponential variation</b>."}]}, {"topic": "21", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q8", "title": "Alternating current — half-wave rectification &amp; power", "pdf": "9702_s25_qp_42_Q8_Alternating_currents.pdf", "marks": 10, "parts": [{"label": "(a)(i)", "codes": ["21.2.1"], "marks": 1, "answer": "<b>Half-wave</b> rectification."}, {"label": "(a)(ii)", "codes": ["21.1.4"], "marks": 1, "answer": "V₀ = √2 × V<sub>r.m.s.</sub> = √2 × 6.0<br>= <b>8.5 V</b>"}, {"label": "(b)(i)", "codes": ["21.1.3"], "marks": 2, "answer": "P = V²/R, so P₀ = V₀²/R = 8.5²/45<br>= <b>1.6 W</b>"}, {"label": "(b)(ii)", "codes": ["21.2.1", "21.1.3"], "marks": 3, "answer": "Over two cycles (t = 0 to 2T): <b>two humps of width 0.5T</b> separated by <b>two sections of zero power of width 0.5T</b>, with peaks at P₀, a smooth sinusoidal shape, and the troughs sitting on the t-axis at P = 0."}, {"label": "(b)(iii)", "codes": ["21.1.3"], "marks": 2, "answer": "Within each hump the mean power is ½P₀ (the average of a sin² half-cycle), and only half of each cycle carries any power, so the overall mean power is ½ × ½P₀ = <b>¼P₀</b>."}, {"label": "(b)(iv)", "codes": ["21.1.4"], "marks": 1, "answer": "⟨P⟩ = V<sub>r.m.s.</sub>²/R, so V<sub>r.m.s.</sub> = √(⟨P⟩R) = √((P₀/4) × 45) = √(1.6 × 45/4)<br>= <b>4.2 V</b>"}]}, {"topic": "22", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q9", "title": "Photoelectric effect — threshold frequency &amp; work function", "pdf": "9702_s25_qp_42_Q9_Quantum_physics.pdf", "marks": 8, "parts": [{"label": "(a)", "codes": ["22.2.1"], "marks": 2, "answer": "The <b>emission of electrons from a metal surface</b> when <b>electromagnetic radiation is incident on it</b>."}, {"label": "(b)(i)", "codes": ["22.2.4"], "marks": 3, "answer": "V<sub>S</sub> is the stopping voltage — the current falls to zero when the applied p.d. equals the energy per unit charge of the most energetic electrons. The <b>energy of a photon depends on the frequency</b> (E = hf), so the <b>maximum energy of the emitted electrons depends on the photon energy</b>, and therefore V<sub>S</sub> depends on the frequency."}, {"label": "(b)(ii)", "codes": ["22.2.2", "22.2.3", "22.2.4"], "marks": 3, "answer": "Any three of: <b>threshold frequency = 1.5 × 10¹⁵ Hz</b>; <b>threshold wavelength = 2.0 × 10⁻⁷ m</b>; <b>work function = 6.2 eV (9.9 × 10⁻¹⁹ J)</b>; <b>Planck constant = 6.6 × 10⁻³⁴ J s</b>; <b>number of photons/electrons per second = 1.7 × 10¹⁶ s⁻¹</b> (in stage 1); <b>power of the incident radiation = 0.028 W</b>."}]}, {"topic": "23", "paper": "9702/42/M/J/25", "paper_full": "June 2025 · Paper 42", "qnum": "Q10", "title": "Radioactive decay — half-life, decay constant &amp; activity", "pdf": "9702_s25_qp_42_Q10_Nuclear_physics.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["23.2.2"], "marks": 1, "answer": "Decay that is <b>not affected by external/environmental factors</b> — it occurs of its own accord."}, {"label": "(b)(i)", "codes": ["23.2.4", "23.2.3", "23.2.5"], "marks": 3, "answer": "From Fig. 10.1, X halves from 4A to 2A at t = 2T and Y halves from A to ½A at t = 3T, so <b>half-life of X = 2T and half-life of Y = 3T</b>.<br>Decay constant λ = ln 2/half-life: λ<sub>X</sub> = ln 2/2T, λ<sub>Y</sub> = ln 2/3T.<br>Initial number N₀ = A₀/λ: N₀(X) = 4A/(ln 2/2T) = <b>8AT/ln 2</b> and N₀(Y) = A/(ln 2/3T) = <b>3AT/ln 2</b>."}, {"label": "(b)(ii)", "codes": ["23.2.6"], "marks": 3, "answer": "Equal activities: 4A e^(−λ<sub>X</sub>t) = A e^(−λ<sub>Y</sub>t)<br>4 = e^(t ln 2(1/2T − 1/3T)) = e^(t ln 2/6T)<br>ln 4 = t ln 2/6T → 2 ln 2 = t ln 2/6T<br>t = <b>12T</b>"}, {"label": "(c)", "codes": ["23.2.1"], "marks": 2, "answer": "The count rate is less than the activity because the radiation is <b>emitted in all directions</b> (not just towards the detector), some is <b>absorbed by the air/sample/window of the detector</b>, and some radiation may not register even though it reaches the detector."}]}, {"topic": "13", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q1", "title": "Gravitational potential &amp; field of Mars — satellite orbit", "pdf": "9702_s25_qp_43_Q1_Gravitational_fields.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["13.4.1"], "marks": 2, "answer": "The <b>work done per unit mass</b><br>in moving a small test mass <b>from infinity to the point</b>."}, {"label": "(b)(i)", "codes": ["13.4.3", "13.2.2"], "marks": 3, "answer": "The satellite moves from r₁ = (3.4 + 1.7) × 10⁶ = 5.1 × 10⁶ m to r₂ = (3.4 + 6.8) × 10⁶ = 10.2 × 10⁶ m from the centre of Mars. Using ΔE<sub>P</sub> = GMm(1/r₁ − 1/r₂):<br>5.1 × 10⁸ = 6.67 × 10⁻¹¹ × M × 122 × [(5.1 × 10⁶)⁻¹ − (10.2 × 10⁶)⁻¹]<br>M = <b>6.4 × 10²³ kg</b>"}, {"label": "(b)(ii)", "codes": ["13.4.2"], "marks": 2, "answer": "φ = −GM/R = −(6.67 × 10⁻¹¹ × 6.4 × 10²³)/(3.4 × 10⁶)<br>= <b>−1.3 × 10⁷ J kg⁻¹</b>"}, {"label": "(c)(i)", "codes": ["13.2.4"], "marks": 1, "answer": "The satellite stays over the same point of Mars, so its period equals Mars’s rotation period: <b>Mars takes (just under) 25 hours to rotate once on its axis</b>."}, {"label": "(c)(ii)", "codes": ["13.2.4"], "marks": 1, "answer": "The orbit is <b>equatorial</b>, and/or the satellite orbits <b>in the same direction as the rotation of Mars</b>."}]}, {"topic": "18", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q2", "title": "Helium atom model — Coulomb’s law, electron orbits &amp; field strength", "pdf": "9702_s25_qp_43_Q2_Electric_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["18.3.2"], "marks": 2, "answer": "The (electric) force between two point charges is <b>(directly) proportional to the product of their charges</b> and <b>inversely proportional to the square of their separation</b>."}, {"label": "(b)(i)", "codes": ["18.3.1"], "marks": 1, "answer": "The helium nucleus contains two protons, so its charge is <b>+2e</b>."}, {"label": "(b)(ii)", "codes": ["18.3.2"], "marks": 1, "answer": "F = Qq/(4πε₀r²) = 2 × (1.60 × 10⁻¹⁹)²/[4π × 8.85 × 10⁻¹² × (170 × 10⁻¹²)²]<br>= <b>1.6 × 10⁻⁸ N</b>"}, {"label": "(c)(i)", "codes": ["18.3.2"], "marks": 2, "answer": "The electric force provides the centripetal force: F = mv²/r, so<br>v = √(Fr/m) = √(1.6 × 10⁻⁸ × 170 × 10⁻¹² / 9.11 × 10⁻³¹)<br>= <b>1.7 × 10⁶ m s⁻¹</b>"}, {"label": "(c)(ii)", "codes": ["18.3.2"], "marks": 2, "answer": "v = 2πr/T, so T = 2πr/v = 2π × 170 × 10⁻¹² / (1.7 × 10⁶)<br>= <b>6.2 × 10⁻¹⁶ s</b><br>(Equivalently F = 4π²mr/T² gives the same period.)"}, {"label": "(d)(i)", "codes": ["18.4.1"], "marks": 2, "answer": "E ∝ Q/r². The other electron has charge e at a distance of 340 pm, and the nucleus has charge 2e at 170 pm, so<br>ratio = [e/(340 × 10⁻¹²)²]/[2e/(170 × 10⁻¹²)²] = (170)²/(2 × 340)² = <b>0.13</b>"}, {"label": "(d)(ii)", "codes": ["18.3.2"], "marks": 1, "answer": "The other electron exerts a small repulsive force, so the resultant inward force is slightly less than 1.6 × 10⁻⁸ N — hence the <b>speed of the electron is slightly lower</b> (or its period slightly greater)."}]}, {"topic": "14", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q3", "title": "Specific latent heat — vaporisation vs fusion &amp; ice–water mixture", "pdf": "9702_s25_qp_43_Q3_Temperature.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["14.3.2"], "marks": 2, "answer": "The <b>(thermal) energy per unit mass</b> required to <b>change state at constant temperature</b>."}, {"label": "(b)", "codes": ["14.3.2"], "marks": 3, "answer": "Vaporisation involves a <b>much larger increase in the separation (or volume) of the molecules</b> than fusion, so <b>much more work has to be done against the intermolecular forces</b> — a much larger increase in molecular potential energy. Since the kinetic energy of the molecules is unchanged in either change of state, more thermal energy is needed to vaporise a substance."}, {"label": "(c)", "codes": ["14.3.1", "14.3.2"], "marks": 4, "answer": "Heat lost by the water = heat to melt the ice + heat to warm the melted water. Using Q = mcΔθ and Q = mL:<br>(37.0 × L) + (37.0 × 4.18 × 10.3) = 208 × 4.18 × (26.4 − 10.3)<br>37.0L + 1593 = 14000<br>L = <b>335 J g⁻¹</b>"}]}, {"topic": "16", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q4", "title": "Internal energy &amp; the first law of thermodynamics", "pdf": "9702_s25_qp_43_Q4_Thermodynamics.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["16.1.1"], "marks": 2, "answer": "The <b>sum of the (randomly distributed) kinetic and potential energies</b> of the particles of the system — the total energy of the random motion of its particles."}, {"label": "(a)(ii)", "codes": ["16.1.1", "15.3.4"], "marks": 2, "answer": "For an ideal gas there are no intermolecular forces, so the <b>potential energy is zero</b> and the internal energy equals the <b>total kinetic energy of the molecules</b>. The average kinetic energy of the molecules is proportional to the (thermodynamic) temperature, so the internal energy is directly proportional to the thermodynamic temperature."}, {"label": "(b)", "codes": ["16.2.2"], "marks": 4, "answer": "<b>Compression</b> (T → 3T): internal energy rises threefold, so ΔU = +2U; work done on the gas = +W. From the first law ΔU = q + W, so thermal energy supplied q = 2U − W.<br><b>Cooling at constant volume</b> (3T → 2T): work done = 0; the internal energy falls from 3U to 2U, so ΔU = −U; hence thermal energy supplied q = ΔU = −U."}]}, {"topic": "17", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q5", "title": "Floating block — simple harmonic motion &amp; energy", "pdf": "9702_s25_qp_43_Q5_Oscillations.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["17.1.1"], "marks": 1, "answer": "The oscillation extends from h = 0.8 m to h = 2.0 m about the equilibrium at h = 1.4 m, so the amplitude = <b>0.60 m</b>."}, {"label": "(a)(ii)", "codes": ["17.1.3"], "marks": 1, "answer": "The line is a straight line through the origin, showing a ∝ −(displacement), so the <b>oscillations are simple harmonic</b>."}, {"label": "(b)", "codes": ["17.1.3", "17.2.2", "17.1.1"], "marks": 3, "answer": "Any three of: the <b>mean/equilibrium position is at h = 1.4 m</b>; the <b>total energy of the oscillations is 9.0 J</b>; the <b>angular frequency is 1.2 rad s⁻¹</b> (period 5.1 s, or frequency 0.19 Hz); the <b>maximum speed is 0.73 m s⁻¹</b>; the <b>mass of the block is 33 kg</b>."}, {"label": "(c)", "codes": ["17.2.1"], "marks": 3, "answer": "A <b>U-shaped curve</b> resting on the h-axis (minimum at E<sub>P</sub> = 0), drawn between h = 0.8 m and h = 2.0 m with the <b>minimum at h = 1.4 m</b> and both end-points at <b>E<sub>P</sub> = 9.0 J</b> (since E<sub>P</sub> = total energy − E<sub>K</sub>)."}]}, {"topic": "21", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q6", "title": "Rectification &amp; smoothing — a.c. to d.c.", "pdf": "9702_s25_qp_43_Q6_Alternating_currents.pdf", "marks": 12, "parts": [{"label": "(a)(i)", "codes": ["21.2.1"], "marks": 1, "answer": "The <b>conversion of an alternating current (a.c.) into a direct current (d.c.)</b>."}, {"label": "(a)(ii)", "codes": ["21.2.4"], "marks": 1, "answer": "To <b>smooth</b> the rectified output (reduce the ripple)."}, {"label": "(b)(i)", "codes": ["21.1.2", "21.1.1"], "marks": 2, "answer": "A = 12 V (the peak value), and B = 2π/T = 2π/(20 × 10⁻³)<br>= <b>310 rad s⁻¹</b>"}, {"label": "(b)(ii)", "codes": ["21.2.1"], "marks": 1, "answer": "<b>Full-wave</b> rectification (both halves of each cycle are used)."}, {"label": "(b)(iii)", "codes": ["21.2.3"], "marks": 2, "answer": "Four diodes connected as a <b>bridge rectifier</b> — a diamond/lattice of four diodes (each with the correct circuit symbol), with the a.c. input connected across one diagonal and the output taken across the other."}, {"label": "(b)(iv)", "codes": ["19.3.3", "21.2.4"], "marks": 3, "answer": "During discharge V = V₀e^(−t/τ). From Fig. 6.2 the p.d. falls from 12 V to 8.0 V in 7.3 ms:<br>8.0 = 12e^(−7.3 × 10⁻³/τ)<br>τ = −7.3 × 10⁻³/ln(8.0/12) = <b>0.018 s</b>"}, {"label": "(c)", "codes": ["19.3.2"], "marks": 2, "answer": "τ = RC, so R = τ/C = 0.018/(570 × 10⁻⁶)<br>= <b>32 Ω</b>"}]}, {"topic": "20", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q7", "title": "Magnetic fields — flux density, force &amp; velocity selector", "pdf": "9702_s25_qp_43_Q7_Magnetic_fields.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["20.2.3"], "marks": 2, "answer": "Magnetic flux density is the <b>force per unit length per unit current</b> acting on a (straight) conductor placed <b>perpendicular to the field</b>."}, {"label": "(b)(i)", "codes": ["20.3.2"], "marks": 1, "answer": "F = <b>BQv</b> (with the velocity perpendicular to the magnetic field)."}, {"label": "(b)(ii)", "codes": ["20.3.1"], "marks": 1, "answer": "An arrow at Y pointing <b>vertically upwards</b> (from Fleming’s left-hand rule for a positive charge)."}, {"label": "(b)(iii)", "codes": ["20.3.5"], "marks": 1, "answer": "A <b>circular path curving upwards</b> through the field (the force is always perpendicular to the velocity, so it acts as a centripetal force)."}, {"label": "(c)(i)", "codes": ["20.3.6"], "marks": 3, "answer": "Apply an <b>electric field vertically downwards</b> so that the <b>electric force on the particle is in the opposite direction to the magnetic force</b>. The particle then passes straight through to Z when the <b>magnitudes of the electric and magnetic forces are equal</b>."}, {"label": "(c)(ii)", "codes": ["20.3.6"], "marks": 2, "answer": "EQ = BQv, so <b>v = E/B</b>."}]}, {"topic": "22", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q8", "title": "Electron &amp; positron — de Broglie wavelength &amp; annihilation", "pdf": "9702_s25_qp_43_Q8_Quantum_physics.pdf", "marks": 13, "parts": [{"label": "(a)", "codes": ["22.3.3"], "marks": 1, "answer": "The <b>wavelength associated with a moving particle</b>."}, {"label": "(b)", "codes": ["22.3.4"], "marks": 2, "answer": "λ = h/p = h/mv = 6.63 × 10⁻³⁴/(9.11 × 10⁻³¹ × 4.9 × 10⁷)<br>= <b>1.5 × 10⁻¹¹ m</b>"}, {"label": "(c)", "codes": ["11.1.8"], "marks": 2, "answer": "Similarity: they have the <b>same mass</b> (or the same magnitude of charge, or both are leptons).<br>Difference: the <b>electron has negative charge while the positron has positive charge</b> (the positron is the antiparticle of the electron)."}, {"label": "(d)(i)", "codes": ["24.3.3"], "marks": 1, "answer": "<b>Annihilation</b> (a particle–antiparticle reaction)."}, {"label": "(d)(ii)", "codes": ["23.1.1", "24.3.3"], "marks": 2, "answer": "The electron and positron disappear — <b>their mass is converted into energy</b>, and this mass–energy becomes the energy of the two gamma-ray photons."}, {"label": "(d)(iii)", "codes": ["24.3.4"], "marks": 1, "answer": "Two photons are produced <b>travelling in opposite directions</b> so that <b>momentum is conserved</b> (the initial total momentum is zero)."}, {"label": "(d)(iv)", "codes": ["22.1.4"], "marks": 1, "answer": "E<sub>k</sub> = ½mv² = ½ × 9.11 × 10⁻³¹ × (4.9 × 10⁷)²<br>= <b>1.1 × 10⁻¹⁵ J</b>"}, {"label": "(d)(v)", "codes": ["23.1.1", "22.1.3"], "marks": 3, "answer": "Each of the two gamma photons carries the rest energy of one particle plus its kinetic energy:<br>E = mc² + E<sub>k</sub> = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² + 1.1 × 10⁻¹⁵ = 8.3 × 10⁻¹⁴ J.<br>Using E = hc/λ:<br>λ = hc/E = (6.63 × 10⁻³⁴ × 3.00 × 10⁸)/(8.3 × 10⁻¹⁴) = <b>2.39 × 10⁻¹² m</b>"}]}, {"topic": "23", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q9", "title": "Radioactive decay — activity, decay constant &amp; half-life", "pdf": "9702_s25_qp_43_Q9_Nuclear_physics.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["23.2.3"], "marks": 1, "answer": "The <b>number of nuclear disintegrations per unit time</b>."}, {"label": "(b)", "codes": ["23.2.6"], "marks": 3, "answer": "The <b>activity is proportional to the number of undecayed nuclei</b> (A = λN), and the activity equals the rate of decrease of N, so dN/dt = −λN — the number of nuclei falls at a rate proportional to itself, giving an <b>exponential variation</b>."}, {"label": "(c)(i)", "codes": ["23.2.6"], "marks": 2, "answer": "A = A₀e^(−λt), so 120 = 180e^(−λ × 8.4)<br>e^(−8.4λ) = 120/180 = 0.667<br>λ = −ln 0.667/8.4 = <b>0.048 min⁻¹</b>"}, {"label": "(c)(ii)", "codes": ["23.2.5"], "marks": 1, "answer": "Half-life = ln 2/λ = ln 2/0.048 = <b>14 min</b>"}, {"label": "(c)(iii)", "codes": ["23.2.6"], "marks": 3, "answer": "An exponential decay curve starting at (0, 180 Bq), with a <b>negative gradient that decreases in magnitude</b>, passing through (8.4, 120) and (14, 90), and approaching the t-axis by t = 24 min."}]}, {"topic": "25", "paper": "9702/43/M/J/25", "paper_full": "June 2025 · Paper 43", "qnum": "Q10", "title": "Hubble’s law &amp; redshift — galaxy recession", "pdf": "9702_s25_qp_43_Q10_Astronomy_and_cosmology.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["25.3.4"], "marks": 2, "answer": "The <b>speed of recession of a galaxy is (directly) proportional to its distance</b> from the observer (v = H₀d), where the speed is that of the galaxy receding from the observer and d is its distance from the observer."}, {"label": "(b)(i)", "codes": ["25.3.2"], "marks": 2, "answer": "The observed wavelength is <b>longer than the emitted wavelength (red-shifted)</b>, so the <b>galaxy is receding from the Earth</b> (the Doppler shift of the light)."}, {"label": "(b)(ii)", "codes": ["25.3.2"], "marks": 2, "answer": "Δλ/λ = v/c<br>(4.91 − 4.62)/4.62 = v/(3.00 × 10⁸)<br>v = <b>1.9 × 10⁷ m s⁻¹</b>"}, {"label": "(b)(iii)", "codes": ["25.2.1"], "marks": 2, "answer": "The wavelength of maximum intensity is <b>inversely proportional to the temperature</b> (Wien’s law). The observed wavelength is too high (red-shifted), so the <b>determined temperature is too low</b> compared with the true value."}, {"label": "(c)", "codes": ["25.3.4"], "marks": 2, "answer": "v = H₀d, so d = v/H₀ = (1.9 × 10⁷)/(2.3 × 10⁻¹⁸)<br>= <b>8.3 × 10²⁴ m</b>"}]}, {"topic": "13", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q1", "title": "Gravitational field &amp; potential of the Earth", "pdf": "9702_s25_qp_44_Q1_Gravitational_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["13.1.1"], "marks": 1, "answer": "Gravitational field is the <b>force per unit mass</b> acting on a small test mass placed at the point."}, {"label": "(b)(i)", "codes": ["13.1.2"], "marks": 2, "answer": "The field lines are <b>radial</b>, pointing <b>towards the centre of the planet</b>."}, {"label": "(b)(ii)", "codes": ["13.3.3"], "marks": 2, "answer": "For small changes in height, the change in height is <b>very much smaller than the radius</b> of the planet, so (R + h)² ≈ R² — the field lines are approximately parallel and g is approximately constant."}, {"label": "(c)(i)", "codes": ["13.3.2"], "marks": 2, "answer": "At the surface g = GM/R², so 9.81 = 3.99 × 10¹⁴/R²<br>R = √(3.99 × 10¹⁴/9.81) = <b>6.38 × 10⁶ m</b>"}, {"label": "(c)(ii)", "codes": ["13.4.2"], "marks": 2, "answer": "φ = −GM/R = −3.99 × 10¹⁴/(6.38 × 10⁶)<br>= <b>−6.25 × 10⁷ J kg⁻¹</b>"}, {"label": "(d)", "codes": ["13.4.1", "13.4.3"], "marks": 2, "answer": "The potential energy is <b>zero at infinite separation</b>, and the gravitational force is <b>attractive</b> — work is done by the field as the masses come together, so the potential energy falls below zero and is always negative."}]}, {"topic": "14", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q2", "title": "Thermal equilibrium — ice melting in water", "pdf": "9702_s25_qp_44_Q2_Temperature.pdf", "marks": 7, "parts": [{"label": "(a)", "codes": ["14.1.2"], "marks": 2, "answer": "The two objects are at the <b>same temperature</b>, so there is <b>no net transfer of thermal energy</b> between them."}, {"label": "(b)(i)", "codes": ["14.3.2"], "marks": 1, "answer": "E₁ = <b>XL</b> (the energy to melt the ice at 0 °C)."}, {"label": "(b)(ii)", "codes": ["14.3.1"], "marks": 1, "answer": "E₂ = <b>Mc(t − θ)</b> (the energy lost by the water cooling from t to θ)."}, {"label": "(b)(iii)", "codes": ["14.3.1"], "marks": 1, "answer": "E₃ = <b>Xcθ</b> (the energy gained by the melted ice warming from 0 °C to θ)."}, {"label": "(c)", "codes": ["14.3.1", "14.3.2"], "marks": 2, "answer": "Energy is conserved: E₂ = E₁ + E₃, so Mc(t − θ) = XL + Xcθ.<br>Mct − Mcθ = XL + Xcθ<br>Mct − XL = θ(Mc + Xc) = θc(M + X)<br>θ = <b>(Mct − XL)/c(M + X)</b>"}]}, {"topic": "15", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q3", "title": "Ideal gas — r.m.s. speed, temperature &amp; internal energy", "pdf": "9702_s25_qp_44_Q3_Ideal_gases.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["15.2.1"], "marks": 2, "answer": "A gas that obeys <b>pV ∝ T</b> at all values of p, V and T, where T is the thermodynamic temperature."}, {"label": "(b)(i)", "codes": ["15.3.2", "15.3.3"], "marks": 3, "answer": "pV = ⅓Nm⟨c²⟩ and Nm/V = ρ, so p = ⅓ρ⟨c²⟩.<br>1.6 × 10⁵ = ⅓ × 1.9 × ⟨c²⟩<br>c<sub>r.m.s.</sub> = √(3 × 1.6 × 10⁵/1.9) = <b>500 m s⁻¹</b>"}, {"label": "(b)(ii)", "codes": ["15.3.4"], "marks": 2, "answer": "½m⟨c²⟩ = (3/2)kT, so T = m⟨c²⟩/(3k)<br>= 4.7 × 10⁻²⁶ × 503²/(3 × 1.38 × 10⁻²³)<br>= <b>290 K</b>"}, {"label": "(c)", "codes": ["16.1.1", "15.3.4"], "marks": 3, "answer": "For an ideal gas the molecular potential energy is zero, so the internal energy is the total kinetic energy: U = N × (3/2)kT.<br>U = 6.0 × 6.02 × 10²³ × (3/2) × 1.38 × 10⁻²³ × 290<br>= <b>21000 J</b>"}]}, {"topic": "17", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q4", "title": "Simple pendulum — frequency &amp; maximum displacement", "pdf": "9702_s25_qp_44_Q4_Oscillations.pdf", "marks": 8, "parts": [{"label": "(a)", "codes": ["17.1.3"], "marks": 2, "answer": "Motion in which the <b>acceleration is (directly) proportional to the displacement</b> and is <b>always directed towards a fixed point</b> (in the opposite direction to the displacement)."}, {"label": "(b)(i)", "codes": ["17.1.1"], "marks": 1, "answer": "The sphere passes through the equilibrium position in the same direction at <b>t₁ and t₅</b> (or t₃ and t₇)."}, {"label": "(b)(ii)", "codes": ["17.1.1"], "marks": 2, "answer": "The interval t₁ → t₆ is 1.25 periods, so T = 2.2/1.25 = 1.76 s.<br>f = 1/T = 1.25/2.2 = <b>0.57 Hz</b>"}, {"label": "(c)", "codes": ["17.1.3", "17.1.4"], "marks": 3, "answer": "v₀ = ωx₀ with ω = 2πf, so x₀ = v₀/(2πf) = 0.080/(2π × 0.57)<br>= <b>0.022 m</b>"}]}, {"topic": "18", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q5", "title": "Charged sphere — electric potential, field &amp; capacitance", "pdf": "9702_s25_qp_44_Q5_Electric_fields.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["18.5.1"], "marks": 2, "answer": "The <b>work done per unit positive charge</b> in moving a small test charge <b>from infinity to the point</b>."}, {"label": "(b)(i)", "codes": ["18.4.1"], "marks": 2, "answer": "E ∝ 1/r², so at the surface (radius r) compared with 3r:<br>E = 3² × 2.0 × 10⁵ = <b>1.8 × 10⁶ N C⁻¹</b>"}, {"label": "(b)(ii)", "codes": ["18.5.3", "18.4.1"], "marks": 2, "answer": "V = Q/4πε₀r and E = Q/4πε₀r², so E = V/r.<br>r = V/E = 9.0 × 10⁴/1.8 × 10⁶ = <b>0.050 m = 5.0 cm</b>"}, {"label": "(b)(iii)", "codes": ["18.5.3"], "marks": 2, "answer": "Q = 4πε₀Vr = 4π × 8.85 × 10⁻¹² × 9.0 × 10⁴ × 0.050<br>= <b>5.0 × 10⁻⁷ C</b>"}, {"label": "(b)(iv)", "codes": ["19.1.2"], "marks": 2, "answer": "C = Q/V = 5.0 × 10⁻⁷/9.0 × 10⁴<br>= <b>5.6 × 10⁻¹² F</b>"}]}, {"topic": "20", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q6", "title": "Coil in a magnetic field — force &amp; torque", "pdf": "9702_s25_qp_44_Q6_Magnetic_fields.pdf", "marks": 10, "parts": [{"label": "(a)(i)", "codes": ["20.2.2"], "marks": 3, "answer": "F = BIL × N = 5.2 × 10⁻³ × 1.2 × 0.054 × 190<br>= <b>0.064 N</b>"}, {"label": "(a)(ii)", "codes": ["20.2.2"], "marks": 2, "answer": "torque = force × perpendicular distance between the forces on QR and PS<br>= 0.064 × 0.025 cos θ = <b>1.6 × 10⁻³ cos θ N m</b>"}, {"label": "(a)(iii)", "codes": ["20.2.2"], "marks": 3, "answer": "One complete cycle of a <b>sinusoidal curve</b> between 0° and 360°, with the τ axis labelled to show maximum and minimum torque at <b>±1.6 × 10⁻³ N m</b>: maximum at 0° and 360°, minimum at 180°, and torque zero at 90° and 270°."}, {"label": "(b)", "codes": ["20.4.2"], "marks": 2, "answer": "The ferrous core <b>increases the magnetic flux density</b>, so the <b>amplitude of the torque increases</b>."}]}, {"topic": "17", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q7", "title": "Damped oscillations — magnet in a coil &amp; electromagnetic induction", "pdf": "9702_s25_qp_44_Q7_Oscillations.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["17.3.1"], "marks": 2, "answer": "Damping is the <b>loss of energy from the oscillations</b> due to <b>resistive forces</b>."}, {"label": "(a)(ii)", "codes": ["17.3.1"], "marks": 1, "answer": "The <b>amplitude of the oscillations decreases gradually</b> (the oscillations continue for several periods)."}, {"label": "(a)(iii)", "codes": ["20.5.4", "20.5.5"], "marks": 3, "answer": "The oscillating magnet <b>cuts magnetic flux</b>, inducing an e.m.f. in the coil. This <b>drives a current through the resistor</b>, which <b>dissipates thermal energy</b>. By conservation of energy this thermal energy comes from the energy of the oscillations, so the oscillations are damped."}, {"label": "(b)", "codes": ["17.3.1", "20.5.4"], "marks": 2, "answer": "For a given induced e.m.f. the <b>current is smaller</b>, so thermal energy is dissipated at a lower rate (the resistive force is smaller). The oscillations are therefore <b>less damped</b> — the amplitude decreases more slowly and they continue for longer."}]}, {"topic": "21", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q8", "title": "Bridge rectifier &amp; smoothing — time constant", "pdf": "9702_s25_qp_44_Q8_Alternating_currents.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["21.2.3"], "marks": 2, "answer": "Four diodes (one in each gap of the bridge), each with the correct circuit symbol, all connected in the correct direction (pointing left to right) so that A is at a positive potential with respect to B."}, {"label": "(b)(i)", "codes": ["21.2.4"], "marks": 3, "answer": "Three lines showing <b>exponential decay from the peaks</b> at 0.5T, 1.0T and 1.5T, ending where the decay meets the next rising peak, with rising portions following the dotted peaks, and a <b>minimum V of (2/3)V₀</b>."}, {"label": "(b)(ii)", "codes": ["19.3.2", "19.3.3"], "marks": 3, "answer": "From the graph the discharge time (from V₀ to (2/3)V₀) is (11/30)T.<br>(2/3)V₀ = V₀ e^(−(11/30)T/τ)<br>ln(2/3) = −11T/30τ<br>τ = <b>0.90 T</b>"}, {"label": "(b)(iii)", "codes": ["19.3.2"], "marks": 2, "answer": "The <b>time constant increases</b> (τ = RC increases with R), so the capacitor discharges more slowly: the <b>minimum voltage is larger</b> (a smaller difference between the maximum and minimum voltages)."}]}, {"topic": "22", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q9", "title": "Wave–particle duality &amp; electron diffraction", "pdf": "9702_s25_qp_44_Q9_Quantum_physics.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["22.3.1", "22.3.2"], "marks": 2, "answer": "Wave–particle duality: an <b>electromagnetic wave can behave like a particle</b>, and a <b>moving particle can behave like a wave</b>."}, {"label": "(a)(ii)", "codes": ["22.3.4"], "marks": 2, "answer": "λ = <b>h/p</b>, where h is the Planck constant and p is the momentum of the particle."}, {"label": "(b)(i)", "codes": ["22.3.2"], "marks": 2, "answer": "The pattern is similar to the <b>diffraction of light</b>, and diffraction is characteristic of wave behaviour — the rings show <b>constructive and destructive interference</b>. This is evidence of a wave nature for the electrons."}, {"label": "(b)(ii)", "codes": ["22.3.4"], "marks": 2, "answer": "The de Broglie wavelength <b>decreases</b> (λ = h/p and p increases), so the <b>rings become closer together</b>."}]}, {"topic": "24", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q10", "title": "Ultrasound — piezoelectric transducer, impedance &amp; attenuation", "pdf": "9702_s25_qp_44_Q10_Medical_physics.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["24.1.1", "24.1.2"], "marks": 3, "answer": "An <b>alternating p.d.</b> is applied across the crystal, causing it to <b>vibrate</b>. When the frequency of the applied p.d. equals the <b>natural frequency</b> of the crystal it <b>resonates</b>, and this natural frequency is in the <b>ultrasound range</b> — so ultrasound waves are generated."}, {"label": "(b)(i)", "codes": ["24.1.4"], "marks": 2, "answer": "Specific acoustic impedance is the <b>product of the density of the medium and the speed of (ultra)sound in the medium</b> (Z = ρc)."}, {"label": "(b)(ii)", "codes": ["24.1.5"], "marks": 2, "answer": "The reflected fraction α is <b>close to 0 when Z₁ and Z₂ are equal</b>, and <b>close to 1 when Z₁ and Z₂ are very different</b>."}, {"label": "(c)", "codes": ["24.1.6"], "marks": 2, "answer": "I = I₀e^(−μx), so ln(I/I₀) = −μx.<br>ln 0.62 = −μ × 2.1<br>μ = <b>0.23 cm⁻¹</b>"}]}, {"topic": "23", "paper": "9702/44/M/J/25", "paper_full": "June 2025 · Paper 44", "qnum": "Q11", "title": "Nuclear fusion in a star — energy, luminosity &amp; temperature", "pdf": "9702_s25_qp_44_Q11_Nuclear_physics.pdf", "marks": 9, "parts": [{"label": "(a)(i)", "codes": ["23.1.2"], "marks": 1, "answer": "<b>Nuclear fusion</b>."}, {"label": "(a)(ii)", "codes": ["23.1.1"], "marks": 3, "answer": "Δm = 0.030377 − (3 × 0.002388) = 0.023213 u (the mass difference between the helium-4 and the three deuterium nuclei).<br>E = Δm c² = 0.023213 × 1.66 × 10⁻²⁷ × (3.00 × 10⁸)²<br>= <b>3.47 × 10⁻¹² J</b>"}, {"label": "(b)(i)", "codes": ["25.1.1", "23.1.1"], "marks": 3, "answer": "Mass of 1 mol of helium-4 = 4 × 10⁻³ kg. Number of helium-4 nuclei produced per second<br>= (6.02 × 10²³ × 7.34 × 10¹¹)/(4 × 10⁻³) = 1.10 × 10³⁸ s⁻¹.<br>Luminosity = (number per second) × (energy per nucleus) = 1.10 × 10³⁸ × 3.47 × 10⁻¹²<br>= <b>3.83 × 10²⁶ W</b>"}, {"label": "(b)(ii)", "codes": ["25.2.2"], "marks": 2, "answer": "L = 4πσr²T⁴<br>3.83 × 10²⁶ = 4π × 5.67 × 10⁻⁸ × (6.96 × 10⁸)² × T⁴<br>T = <b>5770 K</b>"}]}, {"topic": "12", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q1", "title": "Circular motion &amp; simple harmonic motion — shadow projection", "pdf": "9702_w25_qp_41_Q1_Motion_in_a_circle.pdf", "marks": 15, "parts": [{"label": "(a)", "codes": ["12.2.1", "12.2.2"], "marks": 2, "answer": "The velocity and acceleration both have <b>constant magnitude</b>, and the velocity is <b>always perpendicular to the acceleration</b> (the velocity is tangential and the acceleration is directed towards the centre)."}, {"label": "(b)(i)", "codes": ["12.1.3"], "marks": 1, "answer": "v = <b>Rω</b>"}, {"label": "(b)(ii)", "codes": ["12.2.3"], "marks": 2, "answer": "a = Rω² = (Rω)ω = <b>vω</b>"}, {"label": "(c)(i)", "codes": ["17.1.3"], "marks": 1, "answer": "x = <b>R sin θ</b>"}, {"label": "(c)(ii)", "codes": ["12.1.3"], "marks": 1, "answer": "θ = <b>ωt</b>"}, {"label": "(c)(iii)", "codes": ["17.1.3"], "marks": 1, "answer": "Substituting θ = ωt into x = R sin θ gives <b>x = R sin ωt</b>."}, {"label": "(c)(iv)", "codes": ["17.1.3"], "marks": 1, "answer": "The equation is of the form <b>x = x₀ sin ωt</b>, the defining equation of simple harmonic motion (with amplitude x₀ = R), so the shadow's motion is simple harmonic."}, {"label": "(d)(i)", "codes": ["17.1.1"], "marks": 1, "answer": "amplitude = diameter/2 = 0.46/2 = <b>0.23 m</b>"}, {"label": "(d)(ii)", "codes": ["17.1.1"], "marks": 2, "answer": "ω = 2π/T, so T = 2π/ω = 2π/1.9<br>= <b>3.3 s</b>"}, {"label": "(d)(iii)", "codes": ["17.1.3"], "marks": 2, "answer": "a₀ = ω²x₀ = 1.9² × 0.23<br>= <b>0.83 m s⁻²</b>"}, {"label": "(e)", "codes": ["17.1.3"], "marks": 1, "answer": "The shadow is at the extreme of its motion — at the <b>left-hand edge of the circular path</b> (maximum displacement from P), labelled A, where the acceleration is a maximum."}]}, {"topic": "16", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q2", "title": "The first law of thermodynamics — pumping, boiling &amp; vaporisation", "pdf": "9702_w25_qp_41_Q2_Thermodynamics.pdf", "marks": 8, "parts": [{"label": "(a)", "codes": ["16.2.2"], "marks": 2, "answer": "The internal energy can be changed by (1) <b>work done on or by the system</b>, and (2) <b>thermal energy supplied to or removed from the system</b>."}, {"label": "(b)(i)", "codes": ["16.2.1", "16.2.2"], "marks": 3, "answer": "Pumping quickly gives <b>no time for thermal energy to be transferred</b> to or from the gas, while <b>work is done on the gas to compress it</b> (decrease its volume). From the first law ΔU = q + W (with q = 0), the <b>internal energy increases, so the temperature rises</b>."}, {"label": "(b)(ii)", "codes": ["14.3.2", "16.1.2"], "marks": 3, "answer": "During vaporisation the <b>molecular separation increases</b>, so the heating increases the <b>potential energy of the molecules</b> while their <b>kinetic energy is unchanged</b>. Since temperature depends on the kinetic energy, the temperature stays at 100 °C."}]}, {"topic": "13", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q3", "title": "Gravitational field — point masses &amp; two spheres", "pdf": "9702_w25_qp_41_Q3_Gravitational_fields.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["13.1.1"], "marks": 1, "answer": "The <b>force per unit mass</b> acting on a small test mass placed at the point."}, {"label": "(b)(i)", "codes": ["13.3.1"], "marks": 2, "answer": "F = GMm/x² and g = F/m, so g = [GMm/x²]/m = <b>GM/x²</b>, where G is the gravitational constant."}, {"label": "(b)(ii)", "codes": ["13.1.2"], "marks": 1, "answer": "An arrow at P pointing <b>directly towards the point mass</b>."}, {"label": "(b)(iii)", "codes": ["13.3.2"], "marks": 2, "answer": "The field at Q is in the <b>opposite direction</b> to that at P (towards the mass), and is <b>four times the field strength at P</b> (Q is at distance x/2, and g ∝ 1/x²)."}, {"label": "(c)", "codes": ["13.3.2"], "marks": 3, "answer": "A line starting at (R, −g₀) and ending at (L − R, +g₀), passing through (L/2, 0), becoming shallower from R to L/2 and steeper again from L/2 to L − R."}]}, {"topic": "15", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q4", "title": "Absolute zero &amp; ideal gas — molecules, moles &amp; r.m.s. speed", "pdf": "9702_w25_qp_41_Q4_Ideal_gases.pdf", "marks": 10, "parts": [{"label": "(a)(i)", "codes": ["14.2.4"], "marks": 1, "answer": "temperature = <b>−273.15 °C</b>"}, {"label": "(a)(ii)", "codes": ["14.2.4"], "marks": 1, "answer": "temperature = <b>0 K</b>"}, {"label": "(b)(i)", "codes": ["15.2.1"], "marks": 1, "answer": "The graph is a straight line through the origin (pV ∝ kT), so the gas is <b>ideal</b>."}, {"label": "(b)(ii)", "codes": ["15.2.2"], "marks": 2, "answer": "pV = NkT, so N = pV/kT = 270/(8.0 × 10⁻²¹)<br>= <b>3.4 × 10²²</b>"}, {"label": "(b)(iii)", "codes": ["15.1.2"], "marks": 1, "answer": "n = N/N_A = 3.4 × 10²²/(6.02 × 10²³)<br>= <b>0.056 mol</b>"}, {"label": "(c)", "codes": ["15.3.4"], "marks": 4, "answer": "½m⟨c²⟩ = (3/2)kT. When pV = 270 J, kT = 8.0 × 10⁻²¹ J:<br>½ × m × 1900² = 1.5 × 8.0 × 10⁻²¹<br>m = 6.65 × 10⁻²⁷ kg = 6.65 × 10⁻²⁷/(1.66 × 10⁻²⁷) = <b>4.0 u</b>"}]}, {"topic": "18", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q5", "title": "Electric potential — the hydrogen atom dipole", "pdf": "9702_w25_qp_41_Q5_Electric_fields.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["18.5.1"], "marks": 2, "answer": "The <b>work done per unit positive charge</b> in moving a small test charge <b>from infinity to the point</b>."}, {"label": "(b)(i)", "codes": ["18.5.3"], "marks": 2, "answer": "V = (e/4πε₀)(1/10 pm − 1/110 pm) — the proton contributes +e/4πε₀r and the electron −e/4πε₀r.<br>V = (1.60 × 10⁻¹⁹/4π × 8.85 × 10⁻¹²) × [(10⁻¹ − 110⁻¹) × 10¹²] = <b>130 V</b>"}, {"label": "(b)(ii)", "codes": ["18.5.3"], "marks": 2, "answer": "V = (1.60 × 10⁻¹⁹/4π × 8.85 × 10⁻¹²) × [(30⁻¹ − 90⁻¹) × 10¹²]<br>= <b>+32 V</b>"}, {"label": "(b)(iii)", "codes": ["18.5.3"], "marks": 1, "answer": "A cross at the <b>midpoint between the electron and the proton</b> (x = 60 pm), where the +e and −e potentials cancel."}, {"label": "(b)(iv)", "codes": ["18.5.3"], "marks": 3, "answer": "A curve from (10, +130) to (110, −130), getting shallower until x = 60 pm, crossing V = 0 at (60, 0), then getting steeper, and passing through (30, +32) and (90, −32)."}]}, {"topic": "19", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q6", "title": "Capacitors — series/parallel, charge &amp; stored energy", "pdf": "9702_w25_qp_41_Q6_Capacitance.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["19.1.3", "19.1.4"], "marks": 4, "answer": "<b>Series:</b> Q<sub>S</sub> = Q₁ = Q₂ and V<sub>S</sub> = V₁ + V₂.<br><b>Parallel:</b> Q<sub>S</sub> = Q₁ + Q₂ and V<sub>S</sub> = V₁ = V₂."}, {"label": "(b)(i)", "codes": ["19.2.2"], "marks": 2, "answer": "E = ½CV², so V = √(2E/C) = √(2 × 19 × 10⁻³/470 × 10⁻⁶)<br>= <b>9.0 V</b>"}, {"label": "(b)(ii)", "codes": ["19.1.2"], "marks": 2, "answer": "Q = CV = 470 × 10⁻⁶ × 9.0<br>= <b>4.2 × 10⁻³ C</b>"}, {"label": "(b)(iii)", "codes": ["19.2.2"], "marks": 3, "answer": "The total charge is unchanged and the total capacitance is (470 + 180) × 10⁻⁶ F.<br>E = Q²/2C = (4.23 × 10⁻³)²/(2 × 650 × 10⁻⁶)<br>= <b>14 mJ</b>"}]}, {"topic": "20", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q7", "title": "Faraday’s law — induced e.m.f. across an aircraft’s wings", "pdf": "9702_w25_qp_41_Q7_Magnetic_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["20.5.5"], "marks": 2, "answer": "The induced e.m.f. is <b>(directly) proportional to the rate of change of magnetic flux (linkage)</b>."}, {"label": "(b)(i)", "codes": ["20.5.5", "20.5.2"], "marks": 2, "answer": "e.m.f. = ΔΦ/Δt, so flux = e.m.f. × time = 0.54 × 15<br>= <b>8.1 Wb</b>"}, {"label": "(b)(ii)", "codes": ["20.5.2"], "marks": 2, "answer": "Φ = BA, so area = Φ/B = 8.1/(38 × 10⁻⁶)<br>= <b>2.1 × 10⁵ m²</b>"}, {"label": "(b)(iii)", "codes": ["20.5.5"], "marks": 2, "answer": "area = speed × time × width, so v = area/(time × width) = 2.1 × 10⁵/(15 × 68)<br>= <b>210 m s⁻¹</b>"}, {"label": "(b)(iv)", "codes": ["20.5.5", "20.2.2"], "marks": 3, "answer": "By Lenz’s law the induced current produces an opposing force which must act <b>backwards</b>. From Fleming’s left-hand rule the current in the wings is therefore <b>from Q to P</b>. Inside an e.m.f. source the current flows from − to +, so <b>P is at the higher potential</b>."}]}, {"topic": "23", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q8", "title": "Uranium-238 alpha decay — mass, gamma wavelength &amp; neutrinos", "pdf": "9702_w25_qp_41_Q8_Nuclear_physics.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["22.1.1", "22.1.2"], "marks": 2, "answer": "A <b>packet/quantum of energy</b> of <b>electromagnetic radiation</b>."}, {"label": "(b)(i)", "codes": ["23.1.1"], "marks": 3, "answer": "E = Δm c², so Δm = E/c² = (4.274 × 10⁶ × 1.60 × 10⁻¹⁹)/(1.66 × 10⁻²⁷ × (3.00 × 10⁸)²) = 0.00458 u.<br>m = 233.915174 + 4.000407 + 0.00458<br>= <b>237.92016 u</b>"}, {"label": "(b)(ii)", "codes": ["22.1.3", "23.1.1"], "marks": 3, "answer": "The gamma photon carries the remaining energy: 4.274 − 4.200 = 0.074 MeV.<br>E = hc/λ, so λ = hc/E = (6.63 × 10⁻³⁴ × 3.00 × 10⁸)/(0.074 × 1.60 × 10⁻¹³)<br>= <b>1.7 × 10⁻¹¹ m</b>"}, {"label": "(b)(iii)", "codes": ["23.1.1"], "marks": 1, "answer": "The true energy of the gamma photon is <b>smaller</b> (the thorium nucleus carries some kinetic energy), so the <b>true wavelength is larger</b> than the calculated value."}, {"label": "(c)", "codes": ["23.2.2", "11.1.9"], "marks": 2, "answer": "Beta decay also emits <b>(anti)neutrinos</b>, and the particles emitted in beta decay carry <b>varying amounts of energy</b>, so the energy of the gamma photon is variable between decays — there is no single wavelength."}]}, {"topic": "25", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q9", "title": "Wien’s law &amp; luminosity — conclusions about star X", "pdf": "9702_w25_qp_41_Q9_Astronomy_and_cosmology.pdf", "marks": 7, "parts": [{"label": "(a)", "codes": ["25.2.1"], "marks": 2, "answer": "The <b>temperature is inversely proportional to the wavelength</b> at which the <b>maximum emission</b> occurs (λ<sub>max</sub> ∝ 1/T), where T is the thermodynamic temperature of the star’s surface."}, {"label": "(b)", "codes": ["25.2.1", "25.2.2", "25.1.1"], "marks": 3, "answer": "Any three of: <b>star X has a surface temperature of 7000 K</b> (higher than the Sun’s 5770 K); <b>star X has a higher luminosity than the Sun</b>; <b>the luminosity of star X is 2.7 × 10²⁷ W</b>; <b>the radius of star X is 1.3 × 10⁹ m</b>."}, {"label": "(c)", "codes": ["25.3.2"], "marks": 2, "answer": "The light from star X is <b>red-shifted</b> (the galaxy is receding from the Earth), so the <b>wavelength of the peak emission would be greater</b> than its true value."}]}, {"topic": "24", "paper": "9702/41/O/N/25", "paper_full": "November 2025 · Paper 41", "qnum": "Q10", "title": "Ultrasound — acoustic impedance &amp; reflection coefficient", "pdf": "9702_w25_qp_41_Q10_Medical_physics.pdf", "marks": 8, "parts": [{"label": "(a)", "codes": ["24.1.4"], "marks": 2, "answer": "The <b>product of the density of the medium and the speed of sound in the medium</b> (Z = ρc)."}, {"label": "(b)", "codes": ["24.1.2"], "marks": 2, "answer": "The ultrasound waves cause the crystal to <b>vibrate</b>, and these vibrations generate an <b>induced e.m.f.</b> across the crystal, which is then detected."}, {"label": "(c)(i)", "codes": ["24.1.5"], "marks": 2, "answer": "Intensity reflection coefficient = (Z₁ − Z₂)²/(Z₁ + Z₂)²<br>= (40.4 − 1.48)²/(40.4 + 1.48)² = <b>0.86</b>"}, {"label": "(c)(ii)", "codes": ["24.1.5"], "marks": 2, "answer": "The Z values of body tissue and water are <b>very similar</b>, so <b>almost all the ultrasound is transmitted</b> (almost none is reflected)."}]}, {"topic": "12", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q1", "title": "Circular motion of a student at latitude 52.2°", "pdf": "9702_w25_qp_42_Q1_Motion_in_a_circle.pdf", "marks": 9, "parts": [{"label": "(a)(i)", "codes": ["12.1.3"], "marks": 1, "answer": "radius = 6.37 × 10⁶ × cos 52.2°<br>= <b>3.90 × 10⁶ m</b>"}, {"label": "(a)(ii)", "codes": ["12.1.3"], "marks": 3, "answer": "v = 2πr/T = 2π × 3.90 × 10⁶/(24 × 60 × 60)<br>= <b>280 m s⁻¹</b>"}, {"label": "(b)(i)", "codes": ["12.2.4"], "marks": 2, "answer": "F = mv²/r = 58.6 × 280²/(3.90 × 10⁶)<br>= <b>1.2 N</b>"}, {"label": "(b)(ii)", "codes": ["12.2.1"], "marks": 1, "answer": "An arrow pointing <b>horizontally to the left</b> (towards the Earth’s axis of rotation)."}, {"label": "(b)(iii)", "codes": ["12.2.1"], "marks": 2, "answer": "An arrow <b>downwards</b> from the student (towards the centre of the Earth) labelled ‘weight’, and an <b>upwards</b> arrow (the normal contact force) pointing slightly <b>to the left of the normal</b>, labelled ‘contact force’ — their resultant is the horizontal centripetal force."}]}, {"topic": "15", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q2", "title": "Newton’s law &amp; the kinetic theory of gases", "pdf": "9702_w25_qp_42_Q2_Ideal_gases.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["13.2.2"], "marks": 2, "answer": "The gravitational force is <b>(directly) proportional to the product of the two masses</b> and <b>inversely proportional to the square of their separation</b>."}, {"label": "(b)", "codes": ["15.3.1"], "marks": 2, "answer": "Any two of: the molecules are in <b>continuous random motion</b>; the molecules have <b>negligible volume</b> compared with the volume of the gas; the collisions are <b>(perfectly) elastic</b>; the collisions are <b>instantaneous</b>."}, {"label": "(c)(i)", "codes": ["15.2.2"], "marks": 2, "answer": "pV = nRT, so p = nRT/V = 0.0160 × 8.31 × 282/(1.87 × 10⁻⁴)<br>= <b>2.01 × 10⁵ Pa</b>"}, {"label": "(c)(ii)", "codes": ["15.3.1"], "marks": 2, "answer": "number of molecules = 0.0160 × 6.02 × 10²³.<br>separation = ³√(V/N) = ³√[1.87 × 10⁻⁴/(0.0160 × 6.02 × 10²³)]<br>= <b>2.7 × 10⁻⁹ m</b>"}, {"label": "(d)(i)", "codes": ["13.2.2"], "marks": 2, "answer": "F = Gm²/r² = 6.67 × 10⁻¹¹ × (3.34 × 10⁻²⁷)²/(2.7 × 10⁻⁹)²<br>= <b>1.0 × 10⁻⁴⁶ N</b>"}, {"label": "(d)(ii)", "codes": ["13.2.2"], "marks": 1, "answer": "The gravitational force (≈10⁻⁴⁶ N) is enormously smaller than the weight of a molecule (≈mg ≈ 10⁻²⁶ N), so the assumption that there are no forces between the molecules is <b>supported</b>."}]}, {"topic": "14", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q3", "title": "Constant-volume gas thermometer — thermodynamic temperature", "pdf": "9702_w25_qp_42_Q3_Temperature.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["14.1.2"], "marks": 2, "answer": "Two objects are in thermal equilibrium when they are at the <b>same temperature</b>, so there is <b>no net transfer of thermal energy</b> between them."}, {"label": "(b)(i)", "codes": ["14.2.1"], "marks": 1, "answer": "The <b>density</b> of the liquid (used in p = ρgΔh)."}, {"label": "(b)(ii)", "codes": ["14.2.1"], "marks": 2, "answer": "Any two of: a <b>large response time</b> (cannot measure rapidly changing temperatures); reaching equilibrium requires a <b>significant transfer of energy</b> (so it changes the temperature of the environment being measured); it is <b>bulky/difficult to set up</b> and to take readings from."}, {"label": "(b)(iii)", "codes": ["14.2.1"], "marks": 1, "answer": "To measure the temperature of a <b>substance with a large mass</b>, or a <b>constant temperature</b>, or to <b>calibrate other thermometers</b>."}, {"label": "(b)(iv)", "codes": ["14.2.3"], "marks": 3, "answer": "0 °C = 273 K. The temperature is proportional to the pressure (hence Δh):<br>T = 273 × (7.83 − 2.31)/(8.69 − 2.31) = 236 K<br>θ = 236 − 273 = <b>−37 °C</b>"}]}, {"topic": "16", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q4", "title": "The first law — an ideal gas thermodynamic cycle", "pdf": "9702_w25_qp_42_Q4_Thermodynamics.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["16.2.2"], "marks": 2, "answer": "The <b>increase in internal energy = work done on the system + thermal energy transferred to the system by heating</b> (ΔU = q + W)."}, {"label": "(b)(i)", "codes": ["16.1.1"], "marks": 1, "answer": "U = <b>(3/2)pV</b>"}, {"label": "(b)(ii)", "codes": ["15.2.2", "16.1.1"], "marks": 2, "answer": "pV = NkT (k = the Boltzmann constant), so U = <b>(3/2)NkT</b>"}, {"label": "(c)(i)", "codes": ["16.2.1"], "marks": 1, "answer": "W = <b>+8XY</b> (compression — work done on the gas)."}, {"label": "(c)(ii)", "codes": ["16.2.1"], "marks": 1, "answer": "W = <b>−20XY</b> (expansion — work done by the gas)."}, {"label": "(d)", "codes": ["16.2.2"], "marks": 3, "answer": "The work done during BC and DA is zero (constant volume). Over the complete cycle the change in internal energy is zero (the gas returns to A). From the first law, the net thermal energy supplied Q = −(net work done on the gas) = 20XY − 8XY<br>= <b>+12XY</b>"}]}, {"topic": "17", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q5", "title": "Simple harmonic motion &amp; heavy damping — steel ball in oil", "pdf": "9702_w25_qp_42_Q5_Oscillations.pdf", "marks": 10, "parts": [{"label": "(a)(i)", "codes": ["17.1.3"], "marks": 2, "answer": "The graph is a <b>straight line through the origin</b>, showing a is proportional to x, and its <b>negative gradient</b> shows a is always in the opposite direction to x — so the oscillations are simple harmonic."}, {"label": "(a)(ii)", "codes": ["17.1.3"], "marks": 3, "answer": "a₀ = ω²x₀ and ω = 2π/T, so T = 2π√(x₀/a₀) = 2π√(1.2/13)<br>= <b>1.9 s</b>"}, {"label": "(b)(i)", "codes": ["17.3.1"], "marks": 2, "answer": "Damping is the <b>loss of energy from the oscillations</b> due to <b>resistive forces</b>."}, {"label": "(b)(ii)", "codes": ["17.3.2"], "marks": 3, "answer": "A line starting at x = ±1.2 cm at t = 0 (entirely above or below the t-axis), with both the magnitude of x and the magnitude of the gradient <b>continuously decreasing</b> — heavy damping, so the ball returns to equilibrium without oscillating."}]}, {"topic": "18", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q6", "title": "Isolated charged sphere — field, potential &amp; discharge", "pdf": "9702_w25_qp_42_Q6_Electric_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["18.1.1"], "marks": 1, "answer": "The <b>force per unit positive charge</b> acting on a small test charge placed at the point."}, {"label": "(b)(i)", "codes": ["18.1.3"], "marks": 2, "answer": "Radial lines, <b>pointing away from the sphere</b> (the sphere is positively charged)."}, {"label": "(b)(ii)", "codes": ["19.1.2"], "marks": 2, "answer": "C = Q/V, so V = Q/C = 83 × 10⁻¹²/(69 × 10⁻¹²)<br>= <b>1.2 V</b>"}, {"label": "(b)(iii)", "codes": ["18.5.3"], "marks": 2, "answer": "V = Q/4πε₀r, so r = Q/4πε₀V = 83 × 10⁻¹²/(4π × 8.85 × 10⁻¹² × 1.2)<br>= <b>0.62 m</b>"}, {"label": "(b)(iv)", "codes": ["18.4.1"], "marks": 2, "answer": "E = Q/4πε₀r² = 83 × 10⁻¹²/(4π × 8.85 × 10⁻¹² × 0.62²)<br>= <b>1.9 N C⁻¹</b> (or V m⁻¹)"}, {"label": "(c)", "codes": ["19.3.3"], "marks": 2, "answer": "Q = Q₀e^(−t/RC), so 26 = 83e^(−t/(120 × 10⁶ × 69 × 10⁻¹²))<br>t = <b>9.6 × 10⁻³ s</b>"}]}, {"topic": "21", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q7", "title": "Alternating voltage — period, r.m.s. &amp; rectification", "pdf": "9702_w25_qp_42_Q7_Alternating_currents.pdf", "marks": 8, "parts": [{"label": "(a)(i)", "codes": ["21.1.1"], "marks": 1, "answer": "T = 2π/ω = 2π/40π = <b>0.050 s</b>"}, {"label": "(a)(ii)", "codes": ["21.1.4"], "marks": 1, "answer": "V<sub>r.m.s.</sub> = 18/√2 = <b>13 V</b>"}, {"label": "(b)", "codes": ["21.1.2"], "marks": 3, "answer": "A <b>sinusoidal curve of period 50 ms</b> from t = 0 to t = 100 ms, with V<sub>max</sub> at t = 0, 50, 100 ms and −V<sub>max</sub> at t = 25, 75 ms, and the maxima/minima at <b>±18 V</b>."}, {"label": "(c)", "codes": ["21.2.1", "21.1.3", "21.1.4"], "marks": 3, "answer": "Any three of: the <b>rectification is full-wave</b>; the <b>mean power is 14 W</b>; the <b>resistance of R is 12 Ω</b>; the <b>peak current in R is 1.6 A</b> (r.m.s. current 1.1 A); the <b>period of the output is 25 ms</b> (frequency 40 Hz, or angular frequency 250 rad s⁻¹)."}]}, {"topic": "22", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q8", "title": "Hydrogen energy levels — line spectra &amp; photon energies", "pdf": "9702_w25_qp_42_Q8_Quantum_physics.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["22.4.2", "22.4.3"], "marks": 3, "answer": "Any three of: an electron moving between levels <b>emits a single photon</b>; the <b>energy of the photon equals the difference between the energy levels</b>; the <b>photon energy depends on frequency</b> (E = hf); the spectrum has <b>discrete frequencies</b>, so the differences between electron energies (and hence the levels themselves) must be <b>discrete</b>."}, {"label": "(b)(i)", "codes": ["22.4.3"], "marks": 1, "answer": "E = −13.6 × 1.60 × 10⁻¹⁹ = <b>−2.18 × 10⁻¹⁸ J</b>"}, {"label": "(b)(ii)", "codes": ["22.4.3"], "marks": 2, "answer": "ΔE = hf = (6.63 × 10⁻³⁴ × 2.47 × 10¹⁵)/(1.60 × 10⁻¹⁹)<br>= <b>10.2 eV</b>"}, {"label": "(b)(iii)", "codes": ["22.4.1"], "marks": 4, "answer": "n = 2 level = −13.6 + 10.2 = <b>−3.4 eV</b>.<br>n = 3 energy difference = 12.1 eV, so n = 3 = −13.6 + 12.1 = <b>−1.5 eV</b>.<br>n = 4 energy difference = 12.8 eV, so n = 4 = −13.6 + 12.8 = <b>−0.8 eV</b>."}]}, {"topic": "23", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q9", "title": "Nuclear fusion &amp; Sirius — mass defect, luminosity &amp; temperature", "pdf": "9702_w25_qp_42_Q9_Nuclear_physics.pdf", "marks": 13, "parts": [{"label": "(a)", "codes": ["23.1.1"], "marks": 2, "answer": "The <b>difference between the mass of the nucleus and the mass of its constituent nucleons</b> (when the nucleons are separated to infinity)."}, {"label": "(b)", "codes": ["23.1.1"], "marks": 4, "answer": "Δm = (2 × 2.013553) − 4.001505 = 0.025601 u.<br>Energy per helium-4 nucleus = Δm c² = 0.025601 × 1.66 × 10⁻²⁷ × (3.00 × 10⁸)² = 3.82 × 10⁻¹² J.<br>Energy for 1.00 mol = 3.82 × 10⁻¹² × 6.02 × 10²³ = <b>2.30 × 10¹² J</b>"}, {"label": "(c)(i)", "codes": ["25.1.1", "23.1.1"], "marks": 2, "answer": "L = mc² (mass lost per second) = 1.09 × 10¹¹ × (3.00 × 10⁸)²<br>= <b>9.81 × 10²⁷ W</b>"}, {"label": "(c)(ii)", "codes": ["25.2.2"], "marks": 2, "answer": "L = 4πσr²T⁴<br>9.81 × 10²⁷ = 4π × 5.67 × 10⁻⁸ × (1.19 × 10⁹)² × T⁴<br>T = <b>9930 K</b>"}, {"label": "(d)", "codes": ["25.1.3", "25.1.4"], "marks": 3, "answer": "Standard candles have a <b>known luminosity</b>. Measure the <b>radiant flux intensity</b> from the galaxy on the Earth, then use <b>F = L/(4πd²)</b> to calculate the distance d."}]}, {"topic": "24", "paper": "9702/42/O/N/25", "paper_full": "November 2025 · Paper 42", "qnum": "Q10", "title": "X-rays — attenuation, contrast &amp; CT scanning", "pdf": "9702_w25_qp_42_Q10_Medical_physics.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["24.2.2"], "marks": 1, "answer": "Contrast is the <b>difference in the degrees of blackening</b> between different parts of the image."}, {"label": "(b)(i)", "codes": ["24.2.3"], "marks": 1, "answer": "Region B passes through 5.8 cm of P only:<br>I = I₀e^(−μx) = I₀e^(−0.35 × 5.8) = <b>0.13 I₀</b>"}, {"label": "(b)(ii)", "codes": ["24.2.3"], "marks": 3, "answer": "Region A passes through (5.8 − 2.1) = 3.7 cm of P and 2.1 cm of Q:<br>0.053I₀ = I₀e^(−(0.35 × 3.7 + 2.1μ))<br>0.35 × 3.7 + 2.1μ = −ln 0.053 = 2.94<br>μ = <b>0.78 cm⁻¹</b>"}, {"label": "(b)(iii)", "codes": ["24.2.2"], "marks": 1, "answer": "The two emerging intensities differ by only a factor of <b>about 2.5</b> (0.13 vs 0.053), so the contrast between the regions is <b>poor</b>."}, {"label": "(c)", "codes": ["24.2.4"], "marks": 3, "answer": "The structure is <b>scanned in thin sections</b>, with <b>many scans taken from different angles</b> around each section. The scanning is repeated for all sections and the data are <b>compiled to form a 3D image</b>."}]}, {"topic": "12", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q1", "title": "Circular motion &amp; simple harmonic motion — shadow projection", "pdf": "9702_w25_qp_43_Q1_Motion_in_a_circle.pdf", "marks": 15, "parts": [{"label": "(a)", "codes": ["12.2.1", "12.2.2"], "marks": 2, "answer": "The velocity and acceleration both have <b>constant magnitude</b>, and the velocity is <b>always perpendicular to the acceleration</b> (the velocity is tangential and the acceleration is directed towards the centre)."}, {"label": "(b)(i)", "codes": ["12.1.3"], "marks": 1, "answer": "v = <b>Rω</b>"}, {"label": "(b)(ii)", "codes": ["12.2.3"], "marks": 2, "answer": "a = Rω² = (Rω)ω = <b>vω</b>"}, {"label": "(c)(i)", "codes": ["17.1.3"], "marks": 1, "answer": "x = <b>R sin θ</b>"}, {"label": "(c)(ii)", "codes": ["12.1.3"], "marks": 1, "answer": "θ = <b>ωt</b>"}, {"label": "(c)(iii)", "codes": ["17.1.3"], "marks": 1, "answer": "Substituting θ = ωt into x = R sin θ gives <b>x = R sin ωt</b>."}, {"label": "(c)(iv)", "codes": ["17.1.3"], "marks": 1, "answer": "The equation is of the form <b>x = x₀ sin ωt</b>, the defining equation of simple harmonic motion (with amplitude x₀ = R), so the shadow's motion is simple harmonic."}, {"label": "(d)(i)", "codes": ["17.1.1"], "marks": 1, "answer": "amplitude = diameter/2 = 0.46/2 = <b>0.23 m</b>"}, {"label": "(d)(ii)", "codes": ["17.1.1"], "marks": 2, "answer": "ω = 2π/T, so T = 2π/ω = 2π/1.9<br>= <b>3.3 s</b>"}, {"label": "(d)(iii)", "codes": ["17.1.3"], "marks": 2, "answer": "a₀ = ω²x₀ = 1.9² × 0.23<br>= <b>0.83 m s⁻²</b>"}, {"label": "(e)", "codes": ["17.1.3"], "marks": 1, "answer": "The shadow is at the extreme of its motion — at the <b>left-hand edge of the circular path</b> (maximum displacement from P), labelled A, where the acceleration is a maximum."}]}, {"topic": "16", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q2", "title": "The first law of thermodynamics — pumping, boiling &amp; vaporisation", "pdf": "9702_w25_qp_43_Q2_Thermodynamics.pdf", "marks": 8, "parts": [{"label": "(a)", "codes": ["16.2.2"], "marks": 2, "answer": "The internal energy can be changed by (1) <b>work done on or by the system</b>, and (2) <b>thermal energy supplied to or removed from the system</b>."}, {"label": "(b)(i)", "codes": ["16.2.1", "16.2.2"], "marks": 3, "answer": "Pumping quickly gives <b>no time for thermal energy to be transferred</b> to or from the gas, while <b>work is done on the gas to compress it</b> (decrease its volume). From the first law ΔU = q + W (with q = 0), the <b>internal energy increases, so the temperature rises</b>."}, {"label": "(b)(ii)", "codes": ["14.3.2", "16.1.2"], "marks": 3, "answer": "During vaporisation the <b>molecular separation increases</b>, so the heating increases the <b>potential energy of the molecules</b> while their <b>kinetic energy is unchanged</b>. Since temperature depends on the kinetic energy, the temperature stays at 100 °C."}]}, {"topic": "13", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q3", "title": "Gravitational field — point masses &amp; two spheres", "pdf": "9702_w25_qp_43_Q3_Gravitational_fields.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["13.1.1"], "marks": 1, "answer": "The <b>force per unit mass</b> acting on a small test mass placed at the point."}, {"label": "(b)(i)", "codes": ["13.3.1"], "marks": 2, "answer": "F = GMm/x² and g = F/m, so g = [GMm/x²]/m = <b>GM/x²</b>, where G is the gravitational constant."}, {"label": "(b)(ii)", "codes": ["13.1.2"], "marks": 1, "answer": "An arrow at P pointing <b>directly towards the point mass</b>."}, {"label": "(b)(iii)", "codes": ["13.3.2"], "marks": 2, "answer": "The field at Q is in the <b>opposite direction</b> to that at P (towards the mass), and is <b>four times the field strength at P</b> (Q is at distance x/2, and g ∝ 1/x²)."}, {"label": "(c)", "codes": ["13.3.2"], "marks": 3, "answer": "A line starting at (R, −g₀) and ending at (L − R, +g₀), passing through (L/2, 0), becoming shallower from R to L/2 and steeper again from L/2 to L − R."}]}, {"topic": "15", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q4", "title": "Absolute zero &amp; ideal gas — molecules, moles &amp; r.m.s. speed", "pdf": "9702_w25_qp_43_Q4_Ideal_gases.pdf", "marks": 10, "parts": [{"label": "(a)(i)", "codes": ["14.2.4"], "marks": 1, "answer": "temperature = <b>−273.15 °C</b>"}, {"label": "(a)(ii)", "codes": ["14.2.4"], "marks": 1, "answer": "temperature = <b>0 K</b>"}, {"label": "(b)(i)", "codes": ["15.2.1"], "marks": 1, "answer": "The graph is a straight line through the origin (pV ∝ kT), so the gas is <b>ideal</b>."}, {"label": "(b)(ii)", "codes": ["15.2.2"], "marks": 2, "answer": "pV = NkT, so N = pV/kT = 270/(8.0 × 10⁻²¹)<br>= <b>3.4 × 10²²</b>"}, {"label": "(b)(iii)", "codes": ["15.1.2"], "marks": 1, "answer": "n = N/N_A = 3.4 × 10²²/(6.02 × 10²³)<br>= <b>0.056 mol</b>"}, {"label": "(c)", "codes": ["15.3.4"], "marks": 4, "answer": "½m⟨c²⟩ = (3/2)kT. When pV = 270 J, kT = 8.0 × 10⁻²¹ J:<br>½ × m × 1900² = 1.5 × 8.0 × 10⁻²¹<br>m = 6.65 × 10⁻²⁷ kg = 6.65 × 10⁻²⁷/(1.66 × 10⁻²⁷) = <b>4.0 u</b>"}]}, {"topic": "18", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q5", "title": "Electric potential — the hydrogen atom dipole", "pdf": "9702_w25_qp_43_Q5_Electric_fields.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["18.5.1"], "marks": 2, "answer": "The <b>work done per unit positive charge</b> in moving a small test charge <b>from infinity to the point</b>."}, {"label": "(b)(i)", "codes": ["18.5.3"], "marks": 2, "answer": "V = (e/4πε₀)(1/10 pm − 1/110 pm) — the proton contributes +e/4πε₀r and the electron −e/4πε₀r.<br>V = (1.60 × 10⁻¹⁹/4π × 8.85 × 10⁻¹²) × [(10⁻¹ − 110⁻¹) × 10¹²] = <b>130 V</b>"}, {"label": "(b)(ii)", "codes": ["18.5.3"], "marks": 2, "answer": "V = (1.60 × 10⁻¹⁹/4π × 8.85 × 10⁻¹²) × [(30⁻¹ − 90⁻¹) × 10¹²]<br>= <b>+32 V</b>"}, {"label": "(b)(iii)", "codes": ["18.5.3"], "marks": 1, "answer": "A cross at the <b>midpoint between the electron and the proton</b> (x = 60 pm), where the +e and −e potentials cancel."}, {"label": "(b)(iv)", "codes": ["18.5.3"], "marks": 3, "answer": "A curve from (10, +130) to (110, −130), getting shallower until x = 60 pm, crossing V = 0 at (60, 0), then getting steeper, and passing through (30, +32) and (90, −32)."}]}, {"topic": "19", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q6", "title": "Capacitors — series/parallel, charge &amp; stored energy", "pdf": "9702_w25_qp_43_Q6_Capacitance.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["19.1.3", "19.1.4"], "marks": 4, "answer": "<b>Series:</b> Q<sub>S</sub> = Q₁ = Q₂ and V<sub>S</sub> = V₁ + V₂.<br><b>Parallel:</b> Q<sub>S</sub> = Q₁ + Q₂ and V<sub>S</sub> = V₁ = V₂."}, {"label": "(b)(i)", "codes": ["19.2.2"], "marks": 2, "answer": "E = ½CV², so V = √(2E/C) = √(2 × 19 × 10⁻³/470 × 10⁻⁶)<br>= <b>9.0 V</b>"}, {"label": "(b)(ii)", "codes": ["19.1.2"], "marks": 2, "answer": "Q = CV = 470 × 10⁻⁶ × 9.0<br>= <b>4.2 × 10⁻³ C</b>"}, {"label": "(b)(iii)", "codes": ["19.2.2"], "marks": 3, "answer": "The total charge is unchanged and the total capacitance is (470 + 180) × 10⁻⁶ F.<br>E = Q²/2C = (4.23 × 10⁻³)²/(2 × 650 × 10⁻⁶)<br>= <b>14 mJ</b>"}]}, {"topic": "20", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q7", "title": "Faraday’s law — induced e.m.f. across an aircraft’s wings", "pdf": "9702_w25_qp_43_Q7_Magnetic_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["20.5.5"], "marks": 2, "answer": "The induced e.m.f. is <b>(directly) proportional to the rate of change of magnetic flux (linkage)</b>."}, {"label": "(b)(i)", "codes": ["20.5.5", "20.5.2"], "marks": 2, "answer": "e.m.f. = ΔΦ/Δt, so flux = e.m.f. × time = 0.54 × 15<br>= <b>8.1 Wb</b>"}, {"label": "(b)(ii)", "codes": ["20.5.2"], "marks": 2, "answer": "Φ = BA, so area = Φ/B = 8.1/(38 × 10⁻⁶)<br>= <b>2.1 × 10⁵ m²</b>"}, {"label": "(b)(iii)", "codes": ["20.5.5"], "marks": 2, "answer": "area = speed × time × width, so v = area/(time × width) = 2.1 × 10⁵/(15 × 68)<br>= <b>210 m s⁻¹</b>"}, {"label": "(b)(iv)", "codes": ["20.5.5", "20.2.2"], "marks": 3, "answer": "By Lenz’s law the induced current produces an opposing force which must act <b>backwards</b>. From Fleming’s left-hand rule the current in the wings is therefore <b>from Q to P</b>. Inside an e.m.f. source the current flows from − to +, so <b>P is at the higher potential</b>."}]}, {"topic": "23", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q8", "title": "Uranium-238 alpha decay — mass, gamma wavelength &amp; neutrinos", "pdf": "9702_w25_qp_43_Q8_Nuclear_physics.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["22.1.1", "22.1.2"], "marks": 2, "answer": "A <b>packet/quantum of energy</b> of <b>electromagnetic radiation</b>."}, {"label": "(b)(i)", "codes": ["23.1.1"], "marks": 3, "answer": "E = Δm c², so Δm = E/c² = (4.274 × 10⁶ × 1.60 × 10⁻¹⁹)/(1.66 × 10⁻²⁷ × (3.00 × 10⁸)²) = 0.00458 u.<br>m = 233.915174 + 4.000407 + 0.00458<br>= <b>237.92016 u</b>"}, {"label": "(b)(ii)", "codes": ["22.1.3", "23.1.1"], "marks": 3, "answer": "The gamma photon carries the remaining energy: 4.274 − 4.200 = 0.074 MeV.<br>E = hc/λ, so λ = hc/E = (6.63 × 10⁻³⁴ × 3.00 × 10⁸)/(0.074 × 1.60 × 10⁻¹³)<br>= <b>1.7 × 10⁻¹¹ m</b>"}, {"label": "(b)(iii)", "codes": ["23.1.1"], "marks": 1, "answer": "The true energy of the gamma photon is <b>smaller</b> (the thorium nucleus carries some kinetic energy), so the <b>true wavelength is larger</b> than the calculated value."}, {"label": "(c)", "codes": ["23.2.2", "11.1.9"], "marks": 2, "answer": "Beta decay also emits <b>(anti)neutrinos</b>, and the particles emitted in beta decay carry <b>varying amounts of energy</b>, so the energy of the gamma photon is variable between decays — there is no single wavelength."}]}, {"topic": "25", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q9", "title": "Wien’s law &amp; luminosity — conclusions about star X", "pdf": "9702_w25_qp_43_Q9_Astronomy_and_cosmology.pdf", "marks": 7, "parts": [{"label": "(a)", "codes": ["25.2.1"], "marks": 2, "answer": "The <b>temperature is inversely proportional to the wavelength</b> at which the <b>maximum emission</b> occurs (λ<sub>max</sub> ∝ 1/T), where T is the thermodynamic temperature of the star’s surface."}, {"label": "(b)", "codes": ["25.2.1", "25.2.2", "25.1.1"], "marks": 3, "answer": "Any three of: <b>star X has a surface temperature of 7000 K</b> (higher than the Sun’s 5770 K); <b>star X has a higher luminosity than the Sun</b>; <b>the luminosity of star X is 2.7 × 10²⁷ W</b>; <b>the radius of star X is 1.3 × 10⁹ m</b>."}, {"label": "(c)", "codes": ["25.3.2"], "marks": 2, "answer": "The light from star X is <b>red-shifted</b> (the galaxy is receding from the Earth), so the <b>wavelength of the peak emission would be greater</b> than its true value."}]}, {"topic": "24", "paper": "9702/43/O/N/25", "paper_full": "November 2025 · Paper 43", "qnum": "Q10", "title": "Ultrasound — acoustic impedance &amp; reflection coefficient", "pdf": "9702_w25_qp_43_Q10_Medical_physics.pdf", "marks": 8, "parts": [{"label": "(a)", "codes": ["24.1.4"], "marks": 2, "answer": "The <b>product of the density of the medium and the speed of sound in the medium</b> (Z = ρc)."}, {"label": "(b)", "codes": ["24.1.2"], "marks": 2, "answer": "The ultrasound waves cause the crystal to <b>vibrate</b>, and these vibrations generate an <b>induced e.m.f.</b> across the crystal, which is then detected."}, {"label": "(c)(i)", "codes": ["24.1.5"], "marks": 2, "answer": "Intensity reflection coefficient = (Z₁ − Z₂)²/(Z₁ + Z₂)²<br>= (40.4 − 1.48)²/(40.4 + 1.48)² = <b>0.86</b>"}, {"label": "(c)(ii)", "codes": ["24.1.5"], "marks": 2, "answer": "The Z values of body tissue and water are <b>very similar</b>, so <b>almost all the ultrasound is transmitted</b> (almost none is reflected)."}]}, {"topic": "13", "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q1", "title": "Binary star — Newton’s law, orbit &amp; centripetal acceleration", "pdf": "9702_w25_qp_44_Q1_Gravitational_fields.pdf", "marks": 11, "parts": [{"label": "(a)", "codes": ["13.2.2"], "marks": 2, "answer": "The gravitational force is <b>(directly) proportional to the product of the two masses</b> and <b>inversely proportional to the square of their separation</b>."}, {"label": "(b)(i)", "codes": ["13.2.2"], "marks": 2, "answer": "F = Gm₁m₂/r² = 6.67 × 10⁻¹¹ × 4.0 × 10³⁰ × 2.0 × 10³⁰/(3.3 × 10¹²)²<br>= <b>4.9 × 10²⁵ N</b>"}, {"label": "(b)(ii)", "codes": ["13.2.3"], "marks": 1, "answer": "a = F/m = 4.9 × 10²⁵/4.0 × 10³⁰<br>= <b>1.2 × 10⁻⁵ m s⁻²</b>"}, {"label": "(b)(iii)", "codes": ["13.2.3", "12.2.3"], "marks": 3, "answer": "a = rω² with ω = 2π/T. Since R<sub>B</sub> = 2R<sub>A</sub> and R<sub>A</sub> + R<sub>B</sub> = 3.3 × 10¹² m, R<sub>A</sub> = 3.3 × 10¹²/3 = 1.1 × 10¹² m.<br>T = 2π√(r/a) = 2π√(1.1 × 10¹²/1.2 × 10⁻⁵)<br>= <b>1.9 × 10⁹ s</b>"}, {"label": "(b)(iv)", "codes": ["13.2.3", "12.1.3"], "marks": 3, "answer": "centripetal acceleration: <b>B greater than A</b> (a = F/m, and B has the smaller mass); linear speed: <b>B greater than A</b> (v = rω, and B has the larger radius); period: <b>B equal to A</b> (both orbit X with the same period)."}]}, {"topic": "15", "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q2", "title": "Ideal gas — equation of state &amp; r.m.s. speed ratio", "pdf": "9702_w25_qp_44_Q2_Ideal_gases.pdf", "marks": 7, "parts": [{"label": "(a)(i)", "codes": ["15.2.2"], "marks": 3, "answer": "p = the <b>pressure</b> of the gas, V = the <b>volume</b> of the gas, N = the <b>number of molecules</b>, k = the <b>Boltzmann constant</b>, T = the <b>thermodynamic temperature</b>."}, {"label": "(a)(ii)", "codes": ["15.3.4"], "marks": 2, "answer": "pV = NkT = ⅓Nm⟨c²⟩, so m⟨c²⟩ = 3kT.<br>E<sub>k</sub> = ½m⟨c²⟩ = ½ × 3kT = <b>(3/2)kT</b>"}, {"label": "(b)", "codes": ["15.3.3"], "marks": 2, "answer": "At the same temperature ½m⟨c²⟩ is the same for both gases, so c<sub>r.m.s.</sub> ∝ 1/√m.<br>ratio = √(m<sub>O</sub>/m<sub>H</sub>) = √(32/2) = <b>4.0</b>"}]}, {"topic": "16", "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q3", "title": "Internal energy of an ideal gas — changes X and Y", "pdf": "9702_w25_qp_44_Q3_Thermodynamics.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["16.1.1"], "marks": 2, "answer": "For an ideal gas the internal energy is the <b>total kinetic energy of the random motion of the molecules</b>, because the <b>potential energy is zero</b> (there are no intermolecular forces)."}, {"label": "(b)(i)", "codes": ["16.1.1", "15.2.2"], "marks": 2, "answer": "U = (3/2)NkT = (3/2)pV = (3/2) × 2.0 × 10⁵ × 0.016<br>= <b>4800 J</b>"}, {"label": "(b)(ii)", "codes": ["15.2.2"], "marks": 1, "answer": "At constant volume p ∝ T, so doubling the pressure doubles the temperature: T = 400 × 2 = <b>800 K</b>"}, {"label": "(b)(iii)", "codes": ["15.2.2"], "marks": 1, "answer": "At constant temperature pV is constant, so halving the pressure doubles the volume: V = 0.016 × 2 = <b>0.032 m³</b>"}, {"label": "(b)(iv)", "codes": ["15.2.2"], "marks": 3, "answer": "Change X: a <b>straight vertical line</b> from A to B at (0.016, 4.0 × 10⁵), labelled X (constant volume).<br>Change Y: a <b>curve with a continuously decreasing negative gradient</b> from B to C at (0.032, 2.0 × 10⁵), labelled Y (isothermal)."}]}, {"topic": "17", "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q4", "title": "Simple harmonic motion — frequency, energy &amp; interchanges", "pdf": "9702_w25_qp_44_Q4_Oscillations.pdf", "marks": 10, "parts": [{"label": "(a)", "codes": ["17.1.1"], "marks": 1, "answer": "The <b>number of oscillations per unit time</b>."}, {"label": "(b)(i)", "codes": ["17.1.1"], "marks": 1, "answer": "The kinetic energy reaches its maximum/minimum/zero <b>twice in a cycle</b>, so one complete cycle takes 0.80 s."}, {"label": "(b)(ii)", "codes": ["17.1.3"], "marks": 2, "answer": "ω = 2π/T = 2π/0.80<br>= <b>7.9 rad s⁻¹</b> (or ω = √(a₀/x₀) = √(1.0/0.016))"}, {"label": "(b)(iii)", "codes": ["17.1.3", "17.2.2", "17.1.1"], "marks": 3, "answer": "Any three of: the <b>oscillations are simple harmonic</b>; the <b>amplitude = 0.016 m</b>; the <b>maximum speed = 0.13 m s⁻¹</b>; the <b>total energy = 7.0 × 10⁻⁴ J</b>; the <b>mass of the object = 0.087 kg</b>; the <b>maximum momentum = 0.011 kg m s⁻¹</b>."}, {"label": "(b)(iv)", "codes": ["17.2.1"], "marks": 3, "answer": "The kinetic energy is a <b>maximum at zero displacement</b> and <b>zero at maximum displacement</b>, while the potential energy is <b>zero at zero displacement</b> and a <b>maximum at maximum displacement</b>. The <b>sum of the kinetic and potential energies is constant</b> (total energy)."}]}, {"topic": "18", "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q5", "title": "Electric potential &amp; field — proton &amp; charged sphere", "pdf": "9702_w25_qp_44_Q5_Electric_fields.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["18.5.1"], "marks": 3, "answer": "The potential is <b>defined as zero at infinity</b>. The proton has a <b>positive charge</b> and therefore <b>repels another positive charge</b>, so work is done to bring a positive charge in from infinity (or work is done by the charges as they separate) — hence the potential near the proton is positive."}, {"label": "(b)(i)", "codes": ["18.1.3"], "marks": 1, "answer": "An arrow through Q pointing <b>directly away from the centre of the sphere</b> (radially outwards)."}, {"label": "(b)(ii)", "codes": ["18.4.1"], "marks": 3, "answer": "Two lines — one in the top-right quadrant, the other in the bottom-left — passing through (±R, ±E₀) and (±2R, ±¼E₀), with the curve between −3R and −R increasing in gradient magnitude and the curve between R and 3R decreasing in gradient magnitude (nothing drawn between −R and R)."}, {"label": "(c)", "codes": ["18.5.4"], "marks": 2, "answer": "E<sub>P</sub> = −Qq/4πε₀r = −(1.60 × 10⁻¹⁹)²/[4π × 8.85 × 10⁻¹² × 5.3 × 10⁻¹¹]<br>= <b>−4.3 × 10⁻¹⁸ J</b>"}]}, {"topic": 21, "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q6", "title": "Bridge rectifier &amp; smoothing — a.c. to d.c.", "pdf": "9702_w25_qp_44_Q6_Alternating_currents.pdf", "marks": 15, "parts": [{"label": "(a)(i)", "codes": ["21.2.1"], "marks": 1, "answer": "The <b>conversion of an alternating current (a.c.) into a direct current (d.c.)</b>."}, {"label": "(a)(ii)", "codes": ["21.2.1"], "marks": 1, "answer": "<b>Full-wave</b> rectification."}, {"label": "(a)(iii)", "codes": ["21.2.3"], "marks": 2, "answer": "The three missing diodes with correct symbols: the lower-left diode pointing <b>towards the right</b>, and the upper-left and lower-right diodes both pointing <b>towards the left</b>."}, {"label": "(b)(i)", "codes": ["21.1.1"], "marks": 2, "answer": "ω = 18 rad s⁻¹, so T = 2π/ω = 2π/18 = <b>0.35 s</b>"}, {"label": "(b)(ii)", "codes": ["21.1.4"], "marks": 1, "answer": "V<sub>r.m.s.</sub> = 34/√2 = <b>24 V</b>"}, {"label": "(b)(iii)", "codes": ["21.2.1"], "marks": 3, "answer": "Two sinusoidal 'humps' (full-wave rectified), all the same sign, with <b>peak V<sub>OUT</sub> = 34 V</b> and V<sub>OUT</sub> = 0 at t = 0, 0.175 s and 0.35 s (non-zero in between)."}, {"label": "(c)(i)", "codes": ["21.2.4"], "marks": 1, "answer": "A capacitor connected <b>in parallel with the resistor</b>."}, {"label": "(c)(ii)", "codes": ["19.3.2"], "marks": 2, "answer": "τ = RC = 56 × 10³ × 12 × 10⁻⁶ = <b>0.67 s</b>"}, {"label": "(c)(iii)", "codes": ["19.3.3"], "marks": 2, "answer": "V<sub>min</sub> = 34e^(−0.14/0.67) = <b>28 V</b>"}]}, {"topic": 20, "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q7", "title": "Lenz’s law — induced e.m.f. across a helicopter rotor", "pdf": "9702_w25_qp_44_Q7_Magnetic_fields.pdf", "marks": 9, "parts": [{"label": "(a)", "codes": ["20.5.5"], "marks": 2, "answer": "The induced e.m.f. acts in a direction <b>such as to oppose the change that caused it</b>."}, {"label": "(b)(i)", "codes": ["20.5.2"], "marks": 3, "answer": "Φ = BA = 0.047 × 10⁻³ × π × 12²<br>= <b>0.021 Wb</b>"}, {"label": "(b)(ii)", "codes": ["20.5.5"], "marks": 2, "answer": "e.m.f. = flux cut/time = 0.021/(1/85)<br>= <b>1.8 V</b>"}, {"label": "(b)(iii)", "codes": ["20.5.5", "20.2.2"], "marks": 2, "answer": "The force due to the induced current produces an <b>anticlockwise moment</b> (opposing the rotation). From the left-hand rule the current is <b>from O to X</b>, so <b>X is at the higher potential</b>."}]}, {"topic": 23, "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q8", "title": "Oxygen-15 — radioactive decay &amp; PET scanning", "pdf": "9702_w25_qp_44_Q8_Nuclear_physics.pdf", "marks": 15, "parts": [{"label": "(a)", "codes": ["24.3.1"], "marks": 2, "answer": "A tracer is a <b>radioactive substance introduced into the body</b> that is <b>absorbed by the tissues being studied</b>."}, {"label": "(b)(i)", "codes": ["23.1.2", "11.1.6"], "marks": 2, "answer": "P = <b>15</b>, Q = <b>7</b>, R = <b>0</b>, S = <b>+1</b> (¹⁵₈O → ¹⁵₇N + β⁺ + ν)."}, {"label": "(b)(ii)", "codes": ["11.1.9"], "marks": 1, "answer": "An <b>(electron) neutrino</b>."}, {"label": "(c)(i)", "codes": ["23.2.3"], "marks": 1, "answer": "The <b>number of nuclear disintegrations per unit time</b>."}, {"label": "(c)(ii)", "codes": ["23.2.5"], "marks": 2, "answer": "λ = ln 2/t½ = ln 2/(2.04 × 60)<br>= <b>5.66 × 10⁻³ s⁻¹</b>"}, {"label": "(c)(iii)", "codes": ["23.2.3"], "marks": 4, "answer": "N = mass/mass of one atom = 2.85 × 10⁻⁶/(15 × 1.66 × 10⁻²⁷).<br>A = λN = 5.66 × 10⁻³ × 2.85 × 10⁻⁶/(15 × 1.66 × 10⁻²⁷)<br>= <b>6.48 × 10¹⁷ s⁻¹</b>"}, {"label": "(d)(i)", "codes": ["24.3.6"], "marks": 1, "answer": "<b>Gamma-ray photons</b>."}, {"label": "(d)(ii)", "codes": ["24.3.3"], "marks": 2, "answer": "The positron <b>collides with an electron</b> in the body, and <b>annihilation</b> converts their masses into the energy of the gamma photons."}]}, {"topic": 22, "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q9", "title": "Photoelectric effect — threshold frequency &amp; work function", "pdf": "9702_w25_qp_44_Q9_Quantum_physics.pdf", "marks": 8, "parts": [{"label": "(a)", "codes": ["22.2.1"], "marks": 2, "answer": "The <b>emission of electrons from a metal surface</b> when <b>electromagnetic radiation is incident</b> on it."}, {"label": "(b)(i)", "codes": ["22.2.2"], "marks": 1, "answer": "threshold frequency of Y = <b>2F</b> (work function 2Φ = h × 2F)."}, {"label": "(b)(ii)", "codes": ["22.2.4"], "marks": 1, "answer": "Planck constant = <b>Φ/F</b> (since Φ = hF)."}, {"label": "(c)", "codes": ["22.2.4"], "marks": 4, "answer": "Two diagonal straight lines with <b>equal positive gradients</b> (gradient = h) in the positive E<sub>K</sub> region only. Line X passes through (F, 0) and line Y through (2F, 0); X extrapolates back to (0, −Φ) and Y to (0, −2Φ)."}]}, {"topic": 25, "paper": "9702/44/O/N/25", "paper_full": "November 2025 · Paper 44", "qnum": "Q10", "title": "Redshift &amp; Hubble’s law — the expanding universe", "pdf": "9702_w25_qp_44_Q10_Astronomy_and_cosmology.pdf", "marks": 7, "parts": [{"label": "(a)", "codes": ["25.3.1"], "marks": 2, "answer": "Redshift is the <b>increase in observed wavelength (decrease in observed frequency)</b> of light caused by the <b>recession of the galaxy from the observer</b>."}, {"label": "(b)", "codes": ["25.3.3"], "marks": 2, "answer": "Distant galaxies show <b>redshift</b>, so the galaxies are <b>moving apart</b> — which means the universe must be expanding."}, {"label": "(c)", "codes": ["25.3.4"], "marks": 3, "answer": "Hubble’s law states that the <b>speed of recession is proportional to distance</b> (more distant galaxies recede faster). More distant galaxies represent <b>further back in time</b>, so long ago <b>all the matter in the universe must have been very close together</b> (and moving apart very fast) — hence the Big Bang."}]}];